/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A50 staging source: frozen manifest illegal–impeccable; audit and publish every 20 lemmas. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});
D('illegal',{etymology:E('Illegal is formed from the negative prefix il-, a form of in-, plus legal, from Latin legalis, “relating to law.” It means contrary to law; a separate noun sense can describe a person entering or working in a country unlawfully.','illegal'),contexts:[C('illegal.s1','交通规则','The city towed the car because it was parked in an illegal space reserved for emergency access.','市政府拖走了那辆车，因为它停在禁止停车的应急通道上。','The city towed the car / because it was parked in an illegal space / reserved for emergency access.','illegal 表示法律不允许的、违法的。','应急通道禁止停车，停在那里违反规定。')],mistakes:[M('The driver received a fine for legal parking in the emergency lane, where signs clearly prohibited all parking.','The driver received a fine for illegal parking in the emergency lane.','标志明确禁止停车，因此该行为不是合法停车。')],quiz:[Q('illegal',1,1,'An illegal act is?','not allowed by law','required by a contract','popular with the public','not allowed by law','illegal 表示法律禁止或不允许的。'),Q('illegal',2,2,'In a news report, an illegal immigrant is?','a person who entered or works in a country unlawfully','a law that applies to all residents','a person who writes a legal document','a person who entered or works in a country unlawfully','s2 指非法入境或工作的个人，表达时需注意语境。'),Q('illegal',3,1,'Which action is illegal?','parking where a clear sign prohibits it','using a marked public sidewalk','asking a lawyer a question','parking where a clear sign prohibits it','违反明确交通禁令属于违法行为。'),Q('illegal',4,1,'The prefix il- in illegal contributes the sense?','not','before','together','not','il- 在这里是否定前缀。','word-formation')]});
D('illegible',{etymology:E('Illegible is formed from the negative prefix il- and legible, ultimately related to Latin legere, “to read.” It means not clear enough to be read.','illegible'),contexts:[C('illegible.s1','档案管理','The archivist marked the faded address illegible because several letters had disappeared from the old envelope.','档案员把褪色的地址标记为难以辨认，因为旧信封上的几个字母已经消失。','The archivist marked the faded address illegible / because several letters / had disappeared / from the old envelope.','illegible 表示字迹或文字不够清楚，无法读出。','字母褪失使地址无法辨认。')],mistakes:[M('The handwriting was called illegible even though every letter was sharp and easy for the reader to identify.','The handwriting was called legible because every letter was clear.','字迹清楚易读，不符合 illegible。')],quiz:[Q('illegible',1,1,'Illegible writing is?','too unclear to read','written in a foreign language but perfectly clear','famous and widely respected','too unclear to read','illegible 指难以辨认、无法读出的。'),Q('illegible',2,1,'What might make a label illegible?','water smearing the ink','large clear lettering','a bright reading lamp','water smearing the ink','墨水被水洇开后可能无法辨认。'),Q('illegible',3,1,'Illegible is opposite in meaning to?','legible','illegal','illicit','legible','legible 表示清楚可读，与 illegible 相反。'),Q('illegible',4,1,'The prefix il- means?','not','very','again','not','il- 是否定前缀。','word-formation')]});
D('illegitimate',{etymology:E('Illegitimate combines the negative prefix il- with legitimate, from Latin legitimus, “lawful.” It means unauthorized or unjustified; an older legal sense referred to a child born to unmarried parents and is now often avoided.','illegitimate'),contexts:[C('illegitimate.s1','组织治理','The committee rejected the illegitimate vote because the ballot had been submitted after the stated deadline.','委员会拒绝了那张无效投票，因为选票在规定截止时间之后才提交。','The committee rejected the illegitimate vote / because the ballot had been submitted / after the stated deadline.','illegitimate 在此表示未获授权或不符合规则的。','逾期提交的选票不符合委员会的规定。')],mistakes:[M('The board accepted the illegitimate expense because it had been approved through the proper process.','The board rejected the illegitimate expense because it had not been authorized.','已经通过正式程序批准的开支不应称为未经授权。')],quiz:[Q('illegitimate',1,1,'An illegitimate decision is?','not authorized or justified','clearly supported by proper rules','easy to read','not authorized or justified','illegitimate 可表示未经授权或缺乏正当理由。'),Q('illegitimate',2,2,'Historically, illegitimate could refer to?','a child born to unmarried parents','a child who could not read','a person who hosts a meeting','a child born to unmarried parents','s2 是旧式法律称谓，现代语境通常避免使用。'),Q('illegitimate',3,1,'Which claim is illegitimate?','a claim made without authority or evidence','a claim approved by the board','a claim printed in clear type','a claim made without authority or evidence','缺乏授权或依据的主张可称为 illegitimate。'),Q('illegitimate',4,1,'Legitimate means lawful; the prefix il- makes it mean?','not lawful or justified','more lawful','lawful again','not lawful or justified','il- 否定 legitimate 的含义。','word-formation')]});
D('illicit',{etymology:E('Illicit comes from Latin illicitus, from licere, “to be permitted.” It means not permitted by law or custom and can describe a secret or disapproved relationship.','illicit'),contexts:[C('illicit.s1','海关检查','Inspectors found an illicit shipment of protected animal products hidden beneath the declared cargo.','检查人员在申报货物下面发现了一批藏匿的违禁野生动物制品。','Inspectors found an illicit shipment / of protected animal products / hidden beneath / the declared cargo.','illicit 表示法律或惯例不允许的、非法的。','受保护动物制品被藏匿并未申报，属于违禁货物。')],mistakes:[M('The shipment was called illicit even though every item was declared, permitted, and cleared by inspectors.','The shipment was called illicit because protected products were hidden and undeclared.','完全申报并获准的货物不符合非法义。')],quiz:[Q('illicit',1,1,'An illicit trade is?','not permitted by law or custom','officially approved and regulated','a way of making writing legible','not permitted by law or custom','illicit 表示非法或不被允许的。'),Q('illicit',2,2,'An illicit relationship may be?','secret or disapproved','required by a school curriculum','a public award','secret or disapproved','s2 可形容不被认可或隐秘的关系。'),Q('illicit',3,1,'Which shipment is illicit?','hidden goods that regulations prohibit','declared cargo cleared by customs','books shipped to a public library','hidden goods that regulations prohibit','被隐藏且法规禁止的货物属于违禁品。'),Q('illicit',4,1,'Illicit is closest in meaning to?','unlawful','illuminating','immaculate','unlawful','unlawful 与 illicit 意义相近。')]});
D('illiteracy',{etymology:E('Illiteracy is formed from illiterate plus -cy, a suffix forming a state or condition noun. It means inability to read and write, or lack of basic knowledge in a subject.','illiteracy'),contexts:[C('illiteracy.s1','成人教育','The evening class helps adults address literacy needs by practicing everyday reading, forms, and short notes.','夜校通过练习日常阅读、表格和简短便条，帮助成年人弥补读写方面的需要。','The evening class helps adults address literacy needs / by practicing everyday reading / forms / and short notes.','illiteracy 指缺乏读写能力的状态。','课程练习基础阅读与书写技能。')],mistakes:[M('The report described a person who reads books fluently as experiencing illiteracy.','The report used literacy to describe fluent reading and illiteracy for difficulty reading and writing.','能流利阅读的人不属于缺乏读写能力者。')],quiz:[Q('illiteracy',1,1,'Illiteracy is the condition of being unable to?','read and write','speak loudly','remember a name','read and write','illiteracy 指读写能力缺失。'),Q('illiteracy',2,2,'Scientific illiteracy can mean?','lack of basic knowledge about science','difficulty reading printed letters','a person who illustrates books','lack of basic knowledge about science','s2 可比喻对某领域缺乏基础知识。'),Q('illiteracy',3,1,'An adult literacy class aims to reduce?','illiteracy','illumination','immobility','illiteracy','读写课程旨在减少文盲现象。'),Q('illiteracy',4,1,'Illiteracy names a state; its related adjective is?','illiterate','illicit','illustrative','illiterate','illiterate 是相关形容词。','word-formation')]});
D('illiterate',{etymology:E('Illiterate combines the negative prefix il- with literate, from Latin litteratus, “educated or lettered.” It describes someone unable to read or write, someone lacking subject knowledge, or such a person as a noun.','illiterate'),contexts:[C('illiterate.s3','社区服务','The library offers one-to-one support for any illiterate adult who wants help learning to read everyday notices.','图书馆为希望学习阅读日常通知的成年文盲提供一对一帮助。','The library offers one-to-one support / for any illiterate adult / who wants help / learning to read everyday notices.','illiterate 在此作名词，指不会读写的人。','语境以提供学习支持为重点，避免贬义使用。')],mistakes:[M('The notice called an adult illiterate because she had not read one long novel, although she reads and writes fluently.','The notice used illiterate for someone unable to read or write.','没有读过某一本小说不等于不会读写。')],quiz:[Q('illiterate',1,1,'An illiterate person is unable to?','read or write','use a computer at all','understand any spoken language','read or write','illiterate 的核心义是不会读写。'),Q('illiterate',2,2,'A person may be illiterate in a subject if they?','lack basic knowledge of it','cannot read any alphabet','are an expert in it','lack basic knowledge of it','s2 比喻对某领域缺乏基础知识。'),Q('illiterate',3,3,'As a noun, an illiterate is?','a person who cannot read or write','a book illustrator','a legal decision','a person who cannot read or write','s3 将形容词用作名词，指不会读写的人。','grammar'),Q('illiterate',4,1,'Which statement avoids an unfair assumption?','A person can be literate without having read a particular novel.','Anyone who dislikes reading is illiterate.','Illiterate means unable to speak.','A person can be literate without having read a particular novel.','是否读过某本书不能判定读写能力。')]});
D('illness',{etymology:E('Illness is formed from ill plus -ness, a suffix making a noun for a state or condition. It means being ill or having a disease.','illness'),contexts:[C('illness.s1','工作安排','The employee took two days off because of an illness and returned after her fever had passed.','这名员工因病请了两天假，退烧后才回来上班。','The employee took two days off / because of an illness / and returned / after her fever had passed.','illness 指患病的状态或具体疾病。','发烧导致请假，属于健康问题。')],mistakes:[M('The note said the employee missed work because of illness, but explained that she was entirely well and had no disease.','The note said the employee missed work because she was ill.','完全健康、没有不适与 illness 相矛盾。')],quiz:[Q('illness',1,1,'An illness is?','a disease or state of being ill','a legal permission','a bright decoration','a disease or state of being ill','illness 指疾病或患病状态。'),Q('illness',2,1,'Which sentence uses illness correctly?','She stayed home because of a short illness.','The illness decorated the building with lights.','He illness the patient into a hospital.','She stayed home because of a short illness.','因短暂疾病待在家中是自然用法。'),Q('illness',3,1,'A fever may be a sign of?','illness','illiteracy','immensity','illness','发烧可能是患病的迹象。'),Q('illness',4,1,'The suffix -ness turns ill into?','a noun for a condition','a word meaning without','a verb meaning to teach','a noun for a condition','-ness 可把形容词变为状态名词。','word-formation')]});
D('illogical',{etymology:E('Illogical combines the negative prefix il- with logical, from logic. It means contrary to reason or lacking a sound connection between ideas.','illogical'),contexts:[C('illogical.s1','论证分析','The reviewer called the conclusion illogical because the evidence described rainfall while the claim concerned electricity prices.','审稿人认为结论不合逻辑，因为证据讨论的是降雨，而论点涉及电价。','The reviewer called the conclusion illogical / because the evidence described rainfall / while the claim / concerned electricity prices.','illogical 表示不符合推理或逻辑关系的。','降雨数据不能支持电价结论，论据与结论不相连。')],mistakes:[M('The argument was called illogical even though each premise clearly supported the conclusion.','The argument was called logical because its premises supported the conclusion.','前提充分支持结论，不能说推理不合逻辑。')],quiz:[Q('illogical',1,1,'An illogical conclusion is?','not supported by sound reasoning','clearly proved by its premises','too faint to read','not supported by sound reasoning','illogical 指不合逻辑、推理不当的。'),Q('illogical',2,1,'Which reasoning is illogical?','using rainfall data to claim that electricity prices fell','using a sales record to calculate revenue','using a clock to tell the time','using rainfall data to claim that electricity prices fell','降雨数据与电价之间缺少论证联系。'),Q('illogical',3,1,'Illogical is the opposite of?','logical','illegible','illicit','logical','logical 与 illogical 意义相反。'),Q('illogical',4,1,'The prefix il- in illogical means?','not','again','many','not','il- 是否定前缀。','word-formation')]});
D('illuminate',{etymology:E('Illuminate comes from Latin illuminare, “to light up,” formed from in- and lumen, “light.” It can light a place, clarify an idea, decorate a building with lights, or brighten someone’s face with happiness.','illuminate'),contexts:[C('illuminate.s2','科普讲解','The diagram illuminates the process by showing how water moves from the roots through the stem and into the leaves.','这幅图通过展示水分如何从根部经茎部进入叶片，阐明了这一过程。','The diagram illuminates the process / by showing how water moves / from the roots / through the stem and into the leaves.','illuminate 在此表示阐明、使某事更易理解。','图示解释了水分运输路径。')],mistakes:[M('The diagram illuminated the process by removing every label and making the explanation harder to understand.','The diagram illuminated the process by making the water pathway clear.','移除说明并增加理解难度不能称为阐明。')],quiz:[Q('illuminate',1,1,'To illuminate a dark room is to?','light it up','make it harder to understand','make it legally forbidden','light it up','illuminate 的本义是照亮。'),Q('illuminate',2,2,'A chart can illuminate an idea by?','making it easier to understand','decorating a building at night','making a person unable to read','making it easier to understand','s2 表示阐明，使内容易懂。'),Q('illuminate',3,3,'A city may illuminate a building by?','decorating it with lights','covering it in darkness','turning it into a hospital','decorating it with lights','s3 指用灯光装饰建筑。'),Q('illuminate',4,4,'A happy expression may illuminate someone’s face by?','making it look bright with happiness','making the face illegible','making the person illiterate','making it look bright with happiness','s4 比喻喜悦使面容焕发。')]});
D('illuminating',{etymology:E('Illuminating is the present participle of illuminate and an adjective. Figuratively, it means giving new understanding or insight into a subject.','illuminating'),contexts:[C('illuminating.s1','访谈报道','The archivist’s interview was illuminating because it explained why the neighborhood map had changed over several decades.','档案员的访谈很有启发性，因为它解释了社区地图为何在几十年间发生变化。','The archivist’s interview was illuminating / because it explained / why the neighborhood map / had changed over several decades.','illuminating 形容能带来新认识或启发的内容。','访谈解释变化原因，令读者获得新理解。')],mistakes:[M('The report was illuminating, but it concealed every relevant fact and left readers with less understanding.','The report was illuminating because it clarified the relevant facts.','遮蔽事实、降低理解程度与启发义相反。')],quiz:[Q('illuminating',1,1,'An illuminating explanation gives readers?','new understanding','a false visual image','a disease','new understanding','illuminating 表示有启发性、增进理解的。'),Q('illuminating',2,1,'Which source might be illuminating?','an interview that reveals why a decision was made','a blank page with no information','a confusing note with missing words','an interview that reveals why a decision was made','解释决策原因的访谈能带来新认识。'),Q('illuminating',3,1,'Illuminating is related to which verb?','illuminate','immolate','imitate','illuminate','illuminating 是 illuminate 的分词形容词。','word-formation'),Q('illuminating',4,1,'A book review calls a chapter illuminating because it?','clarifies an unfamiliar topic','makes all writing impossible to read','contains only empty boasts','clarifies an unfamiliar topic','阐明陌生主题使内容有启发性。')]});
D('illumination',{etymology:E('Illumination comes from Latin illuminatio, from illuminare, “to light up.” It means the lighting of a place or the light itself, and can also mean a moment of understanding that clarifies a difficult point.','illumination'),contexts:[C('illumination.s1','建筑设计','The gallery’s soft illumination makes the paintings visible without exposing the pigments to harsh bright light.','展厅柔和的照明让画作清晰可见，同时避免颜料受到强光照射。','The gallery’s soft illumination / makes the paintings visible / without exposing the pigments / to harsh bright light.','illumination 在此指照明或提供的光线。','柔和灯光让作品可见并保护颜料。')],mistakes:[M('The gallery described its complete darkness as bright illumination, although no lamps or daylight were present.','The gallery described the soft light on the paintings as illumination.','完全黑暗中没有照明。')],quiz:[Q('illumination',1,1,'Illumination in a gallery refers to?','lighting or light in the space','a person’s inability to read','a secret relationship','lighting or light in the space','illumination 可指照明或光线。'),Q('illumination',2,2,'A sudden illumination about a puzzle is?','a moment of understanding','a flash from a car horn','a feeling of illness','a moment of understanding','s2 比喻对难题突然理解。'),Q('illumination',3,1,'Which provides illumination?','a lamp lighting a reading desk','a locked empty drawer','a silent conversation','a lamp lighting a reading desk','灯具为桌面提供照明。'),Q('illumination',4,1,'Illumination is formed from the verb?','illuminate','illustrate','imitate','illuminate','illumination 是 illuminate 的名词形式。','word-formation')]});
D('illusion',{etymology:E('Illusion comes from Latin illusio, “a mocking or deceiving,” from illudere, “to play with or deceive.” It can mean something seeming real but not matching reality, a false belief, or a misleading appearance.','illusion'),contexts:[C('illusion.s1','视觉艺术','The painted hallway creates the illusion of depth, although the wall is perfectly flat.','彩绘走廊营造出有纵深的错觉，尽管墙面完全平坦。','The painted hallway creates the illusion of depth / although the wall / is perfectly flat.','illusion 在此指看似真实但与实际情况不同的视觉效果。','平墙看起来有纵深，是视觉错觉。')],mistakes:[M('The artist called the flat wall an illusion of depth even though it physically extended several meters into the room.','The artist created an illusion of depth on the flat wall.','真实存在的实体深度不是由平面图像造成的错觉。')],quiz:[Q('illusion',1,1,'An optical illusion is?','something that appears different from reality','a clear legal authorization','a type of reading skill','something that appears different from reality','illusion 可指视觉上看似存在而实际不同的东西。'),Q('illusion',2,2,'“The illusion that everyone agreed” is?','a false belief','a bright decoration','a type of insect','a false belief','s2 指对事实的错误看法。'),Q('illusion',3,3,'A mirror can create an illusion of?','space beyond the actual wall','a hospital admission','a household chore','space beyond the actual wall','镜面可造成墙后还有空间的视觉表象。'),Q('illusion',4,1,'Which is an illusion?','a flat painting that seems three-dimensional','a real deep tunnel','a legible printed map','a flat painting that seems three-dimensional','平面画作看似立体属于错觉。')]});
D('illusive',{etymology:E('Illusive comes from Latin illudere, “to deceive or mock,” through illusion. It means not real despite appearing to be real; illusory is a more common near-synonym.','illusive'),contexts:[C('illusive.s1','沙漠旅行','The distant lake proved illusive; as the travelers approached, the shimmering water vanished from view.','远处的湖原来只是虚幻景象；旅行者走近时，闪烁的水面便消失了。','The distant lake proved illusive / as the travelers approached / the shimmering water / vanished from view.','illusive 表示看似真实但其实并不存在的。','水面幻象随着接近而消失。')],mistakes:[M('The map called the river illusive even though it flowed year-round and was clearly visible from the bridge.','The map called the mirage illusive because it only seemed to be a real lake.','持续存在且清楚可见的河流并非虚幻景象。')],quiz:[Q('illusive',1,1,'An illusive object?','seems real but is not','is perfectly clear to read','is required by law','seems real but is not','illusive 表示虚幻、造成错觉的。'),Q('illusive',2,1,'Which might be illusive in a desert?','a mirage that looks like a lake','a real water tank','a printed street sign','a mirage that looks like a lake','海市蜃楼看似湖泊，却不是真实水体。'),Q('illusive',3,1,'Illusive is close in meaning to?','illusory','illuminating','illiterate','illusory','illusory 是更常见的近义词。'),Q('illusive',4,1,'If a promise is illusive, it may?','seem attainable but prove unreal','be supported by a signed contract','make a room brighter','seem attainable but prove unreal','虚幻的承诺看似可实现，最终却不真实。')]});
D('illusory',{etymology:E('Illusory comes from Latin illusorius, “deceptive,” related to illudere, “to deceive.” It means false although it looks convincing or real.','illusory'),contexts:[C('illusory.s1','风险分析','The supposed savings were illusory because the low purchase price was outweighed by years of repair costs.','所谓节省其实只是表象，因为较低的购买价格被多年的维修成本抵消了。','The supposed savings were illusory / because the low purchase price / was outweighed / by years of repair costs.','illusory 表示看似真实或有利、实际上并非如此的。','长期维修成本说明节省并不真实。')],mistakes:[M('The savings were called illusory even though the total cost was genuinely lower and no hidden expenses existed.','The savings were called real because the total cost was genuinely lower.','确实降低总成本且没有隐性支出，不符合虚假的 savings。')],quiz:[Q('illusory',1,1,'Illusory savings are?','not real despite seeming convincing','guaranteed and fully documented','difficult to read','not real despite seeming convincing','illusory 表示虚假的、只是表象的。'),Q('illusory',2,1,'Which benefit is illusory?','a discount erased by hidden fees','a verified reduction in total cost','a clear safety improvement','a discount erased by hidden fees','隐藏费用抵消折扣，所谓优惠只是表象。'),Q('illusory',3,1,'Illusory is closest to?','deceptive','immaculate','immediate','deceptive','deceptive 与 illusory 意义相近。'),Q('illusory',4,1,'A convincing but false appearance is?','illusory','hospitable','horizontal','illusory','illusory 可指看似可信实则虚假的表象。')]});
D('illustrate',{etymology:E('Illustrate comes from Latin illustrare, “to light up or make clear.” It means explaining by examples, adding pictures to a publication, or showing something in a picture or diagram.','illustrate'),contexts:[C('illustrate.s1','课堂讲解','The teacher used a small experiment to illustrate how pressure changes when air is compressed.','老师用一个小实验来说明空气被压缩时压力如何变化。','The teacher used a small experiment / to illustrate / how pressure changes / when air is compressed.','illustrate 在此表示通过例子或演示使某事清楚。','实验展示压力变化，帮助解释概念。')],mistakes:[M('The teacher illustrated the rule by giving no example and making the explanation less clear.','The teacher illustrated the rule with a clear experiment and example.','没有例子且降低清晰度不符合说明义。')],quiz:[Q('illustrate',1,1,'To illustrate a point is to?','make it clear with an example','make it impossible to read','declare it illegal','make it clear with an example','illustrate 可通过例子阐明观点。'),Q('illustrate',2,2,'To illustrate a book is to?','add pictures to it','remove its pages','read it aloud','add pictures to it','s2 指为书籍配图。'),Q('illustrate',3,3,'A diagram can illustrate?','how a machine works','the taste of a meal only','a person’s legal status','how a machine works','s3 指用图画或图表展示事物。'),Q('illustrate',4,1,'Which sentence uses illustrate as “explain”?','The case illustrates why the rule matters.','The artist illustrated the children’s book.','She illustrated the flower in watercolor.','The case illustrates why the rule matters.','案例使规则的重要性更清楚。')]});
D('illustration',{etymology:E('Illustration comes from Latin illustratio, from illustrare, “to light up or make clear.” It means a picture printed in a book or an example that clarifies an idea.','illustration'),contexts:[C('illustration.s1','儿童读物','The children paused at each illustration, studying the watercolor animals before turning to the next page.','孩子们每到一幅插图前都会停下来，仔细看水彩动物，然后再翻到下一页。','The children paused at each illustration / studying the watercolor animals / before turning / to the next page.','illustration 在此指印在书中的图画或插图。','孩子们逐幅观看书中的水彩画。')],mistakes:[M('The publisher called a blank page with no image or example an illustration.','The publisher called the printed watercolor picture an illustration.','空白页没有图画，不能称为插图。')],quiz:[Q('illustration',1,1,'An illustration in a book is?','a picture or drawing','a legal ruling','a sound made by a wolf','a picture or drawing','illustration 可指书籍中的插图。'),Q('illustration',2,2,'An illustration of a principle can be?','an example that makes it clearer','a false belief','an inability to read','an example that makes it clearer','s2 指阐明观点的例子。'),Q('illustration',3,1,'Which item is an illustration?','a drawing printed beside a story','a blank page','a spoken rumor with no image','a drawing printed beside a story','故事旁印制的图画是插图。'),Q('illustration',4,1,'Illustration is related to the verb?','illustrate','illness','immerse','illustrate','illustration 是 illustrate 的名词形式。','word-formation')]});
D('illustrative',{etymology:E('Illustrative is formed from illustrate with the adjective suffix -ive. It means serving as an example or helping to explain something.','illustrative'),contexts:[C('illustrative.s1','案例说明','The report included an illustrative case showing how the revised schedule reduced delays at the station.','报告列举了一个说明性案例，展示修订后的时刻表如何减少车站延误。','The report included an illustrative case / showing how the revised schedule / reduced delays / at the station.','illustrative 表示可用作例证或有助于说明的。','案例展示了时刻表改变带来的具体结果。')],mistakes:[M('The report called its illustrative case useless for explaining the change, even though it showed the effect clearly.','The report called its case illustrative because it clearly showed the effect of the change.','清楚展示变化效果的案例有说明作用。')],quiz:[Q('illustrative',1,1,'An illustrative example is one that?','helps explain a point','is impossible to understand','breaks a law','helps explain a point','illustrative 表示说明性的。'),Q('illustrative',2,1,'Which item is illustrative?','a case showing how a new rule works','a blank sheet with no information','a claim contradicted by all evidence','a case showing how a new rule works','展示规则运行方式的案例能说明问题。'),Q('illustrative',3,1,'Illustrative is formed from illustrate plus?','-ive','-ness','-less','-ive','-ive 常构成形容词。','word-formation'),Q('illustrative',4,1,'A graph is illustrative if it?','makes a trend easier to see','hides all the data','causes a disease','makes a trend easier to see','图表能让趋势更清楚，因此具有说明作用。')]});
D('illustrator',{etymology:E('Illustrator is formed from illustrate plus -or, a suffix naming a person who performs an action. It means someone whose work is to create pictures that accompany a text.','illustrator'),contexts:[C('illustrator.s1','出版工作','The illustrator sketched the main characters and sent the finished drawings to the editor before the book went to print.','插画师画出了主要人物草图，并在书籍付印前把完成的图画交给编辑。','The illustrator sketched the main characters / and sent the finished drawings / to the editor / before the book went to print.','illustrator 指为文字作品创作配图的人。','插画师负责绘制书中人物并提交图稿。')],mistakes:[M('The publisher credited the illustrator for proofreading the text but listed no pictures or drawing work.','The publisher credited the illustrator for creating the book’s pictures.','只校对文字而未绘图，不符合插画师的工作义。')],quiz:[Q('illustrator',1,1,'An illustrator creates?','pictures that accompany text','legal rules','hormones','pictures that accompany text','illustrator 指插画师。'),Q('illustrator',2,1,'An illustrator on a children’s book might draw?','characters and scenes','the book’s monthly sales only','a hospital’s floor plan only','characters and scenes','儿童读物插画师常绘制人物和场景。'),Q('illustrator',3,1,'The suffix -or in illustrator often names?','a person who performs an action','a state of being without something','a direction','a person who performs an action','-or 可表示执行某动作的人。','word-formation'),Q('illustrator',4,1,'Which person is an illustrator?','an artist making pictures for a novel','a reader borrowing the novel','a printer repairing a press only','an artist making pictures for a novel','为小说制作配图的艺术家是插画师。')]});
D('illustrious',{etymology:E('Illustrious comes from Latin illustris, “bright or distinguished.” It describes someone very well known and respected because of achievement.','illustrious'),contexts:[C('illustrious.s1','颁奖典礼','The museum honored an illustrious archaeologist whose discoveries transformed understanding of the ancient settlement.','博物馆表彰了一位声名卓著的考古学家，他的发现改变了人们对古代聚落的认识。','The museum honored an illustrious archaeologist / whose discoveries transformed understanding / of the ancient settlement.','illustrious 指因成就而闻名且受人尊敬的。','考古发现影响深远，因此学者声誉卓著。')],mistakes:[M('The article called an unknown visitor illustrious despite noting that the visitor had no public achievements or recognition.','The article called the widely respected archaeologist illustrious because of her discoveries.','毫无知名度和成就的人不符合 illustrious。')],quiz:[Q('illustrious',1,1,'An illustrious person is?','famous and respected for achievements','unable to read handwriting','angry and quick-tempered','famous and respected for achievements','illustrious 表示声名卓著、受人尊敬。'),Q('illustrious',2,1,'Which career might be called illustrious?','a scientist honored for landmark discoveries','a person unknown for any achievement','a temporary noisy crowd','a scientist honored for landmark discoveries','重要发现带来声誉和尊敬。'),Q('illustrious',3,1,'Illustrious is closest to?','renowned','illegible','immobile','renowned','renowned 表示著名，与 illustrious 接近。'),Q('illustrious',4,1,'The Latin source of illustrious was associated with?','brightness or distinction','a house or home','a plant’s growth','brightness or distinction','词源 illūstris 与明亮、卓著相关。','word-formation')]});
D('image',{etymology:E('Image comes through French from Latin imago, “likeness or representation.” It can mean a picture or photograph, a public impression, a mental picture, a reflection, or a vivid poetic expression.','image'),contexts:[C('image.s2','公共关系','The company revised its public image after customers criticized how it handled repairs and warranty claims.','顾客批评公司处理维修和保修索赔的方式后，公司着手改善其公众形象。','The company revised its public image / after customers criticized / how it handled repairs / and warranty claims.','image 在此指公众对个人或机构形成的整体印象。','顾客评价影响公司给公众留下的印象。')],mistakes:[M('The company’s public image improved when it ignored every complaint and made no change to its service.','The company worked to improve its public image by responding to complaints and improving service.','无视投诉且不改善服务难以提升公众印象。')],quiz:[Q('image',1,1,'A digital image may be?','a picture or photograph','a period of sixty minutes','a legal accusation','a picture or photograph','image 可指照片或图像。'),Q('image',2,2,'A company’s image is its?','general public impression','private house key','ability to read','general public impression','s2 指公众印象或形象。'),Q('image',3,3,'An image in someone’s mind is?','a picture formed mentally','a real object in a room','a legal permit','a picture formed mentally','s3 指头脑中形成的画面。'),Q('image',4,5,'A poet’s image is often?','a vivid phrase that helps readers picture an idea','a company’s annual budget','a mirror’s physical frame','a vivid phrase that helps readers picture an idea','s5 指具有画面感的诗性表达。')]});
D('imagery',{etymology:E('Imagery is formed from image with the collective or abstract suffix -ry. It can mean language that appeals to the senses or a collection of pictures and visual representations.','imagery'),contexts:[C('imagery.s1','文学课','The poet’s imagery of cold iron, distant bells, and wet stone makes the abandoned station feel vivid to the reader.','诗人用冰冷的铁、远处的钟声和潮湿的石头等意象，让读者清晰感受到废弃车站。','The poet’s imagery of cold iron / distant bells / and wet stone / makes the abandoned station feel vivid to the reader.','imagery 在此指唤起视觉、听觉或触觉感受的语言。','铁的冷、钟声和湿石构成多感官的文字意象。')],mistakes:[M('The poem’s imagery was described as vivid even though it contained no sensory words or pictures.','The poem’s imagery was described as vivid because its sensory details brought the scene to life.','没有感官描写或视觉呈现的文本不构成生动意象。')],quiz:[Q('imagery',1,1,'Literary imagery consists of words that?','make readers see, hear, or feel a scene','identify a person’s legal status','measure an engine’s power','make readers see, hear, or feel a scene','imagery 可指唤起感官体验的文字。'),Q('imagery',2,2,'A gallery’s imagery may mean its?','pictures and visual representations considered together','lack of reading ability','hostile reactions','pictures and visual representations considered together','s2 指整体图像或视觉材料。'),Q('imagery',3,1,'Which phrase uses sensory imagery?','the sharp scent of rain on warm stone','the budget was approved','the room is 12 meters long','the sharp scent of rain on warm stone','气味和触感细节构成感官意象。'),Q('imagery',4,1,'Imagery is built from which word?','image','illness','impact','image','imagery 与 image 同源。','word-formation')]});
D('imaginary',{etymology:E('Imaginary comes from Latin imaginarius, “existing in imagination,” related to imago, “image.” It describes something not real but created in the mind.','imaginary'),contexts:[C('imaginary.s1','儿童故事','The child gave her imaginary dragon a name and drew a map of the mountain where it supposedly lived.','孩子给想象中的龙取了名字，还画了一张地图，标出它据说居住的山。','The child gave her imaginary dragon a name / and drew a map / of the mountain / where it supposedly lived.','imaginary 表示存在于想象中、并非真实的。','龙是孩子想象出来的角色。')],mistakes:[M('The report called the imaginary dragon a real animal that veterinarians had examined in a clinic.','The story described the dragon as imaginary, a creature created in the child’s mind.','虚构的龙不能同时被当作真实动物接受检查。')],quiz:[Q('imaginary',1,1,'An imaginary friend is?','created in the mind rather than real','a public figure everyone recognizes','a person unable to read','created in the mind rather than real','imaginary 表示想象出来而非真实存在。'),Q('imaginary',2,1,'Which is imaginary?','a dragon in a child’s story','a horse standing in a stable','a photograph of a real building','a dragon in a child’s story','故事中的龙是想象产物。'),Q('imaginary',3,1,'Imaginary is closest to?','fictional','illegal','immobile','fictional','fictional 与 imaginary 意义相近。'),Q('imaginary',4,1,'An imaginary place exists?','only in the imagination','on every official map','inside a hospital','only in the imagination','imaginary 指由心智构想的事物。')]});
D('imagination',{etymology:E('Imagination comes through French from Latin imaginatio, “a forming of mental images,” related to imago, “image.” It means the ability or act of forming new ideas in the mind.','imagination'),contexts:[C('imagination.s1','创意写作','With a little imagination, the students turned an ordinary cardboard box into a model submarine for their science display.','学生们发挥一点想象力，就把普通纸箱做成了科学展览用的潜水艇模型。','With a little imagination / the students turned an ordinary cardboard box / into a model submarine / for their science display.','imagination 指在头脑中创造新想法或形象的能力。','把纸箱构想并改造成潜水艇模型体现创造性思维。')],mistakes:[M('The display showed no imagination because the students copied a finished model without adding any new ideas.','The display showed imagination because the students transformed a plain box into an original model.','完全照搬而没有新构想不体现想象力。')],quiz:[Q('imagination',1,1,'Imagination is the ability to?','form new ideas or pictures in the mind','read every handwriting style','predict an exact legal outcome','form new ideas or pictures in the mind','imagination 指在头脑中构思的能力。'),Q('imagination',2,1,'Which project uses imagination?','turning a box into a model submarine','copying instructions without changes','measuring a room with a ruler','turning a box into a model submarine','把纸箱改造成模型体现想象力。'),Q('imagination',3,1,'Imagination can help a writer?','invent characters and scenes','repair a horse’s hoof','make a room legally permitted','invent characters and scenes','写作者可借想象创造人物与场景。'),Q('imagination',4,1,'Imagination is related to the word?','image','illness','immobility','image','imagination 与 mental image 同源。','word-formation')]});
D('imaginative',{etymology:E('Imaginative is formed from imagination with the adjective suffix -ive. It describes someone able to invent new ideas or something unreal but created in the mind.','imaginative'),contexts:[C('imaginative.s1','产品设计','The imaginative designer turned discarded bicycle parts into a working lamp with an adjustable metal shade.','这位富有创意的设计师把废弃自行车零件改造成一盏可调节金属灯罩的实用台灯。','The imaginative designer / turned discarded bicycle parts / into a working lamp / with an adjustable metal shade.','imaginative 在此形容有创造新想法能力的。','设计师把废旧零件改造成新产品，体现创造力。')],mistakes:[M('The designer was called imaginative for producing only a routine copy with no new idea or variation.','The designer was called imaginative for turning discarded parts into an original lamp.','完全照搬、没有新构想不符合 imaginative。')],quiz:[Q('imaginative',1,1,'An imaginative person is able to?','think of new ideas','avoid forming any mental picture','read only legal documents','think of new ideas','imaginative 表示富有想象力的。'),Q('imaginative',2,2,'An imaginative creature may be?','not real but invented in the mind','a verified animal in a zoo','a person paid to host a show','not real but invented in the mind','s2 可表示想象出来、并不存在的。'),Q('imaginative',3,1,'Which solution is imaginative?','making a lamp from discarded bicycle parts','throwing away all materials without a plan','repeating a failed design exactly','making a lamp from discarded bicycle parts','利用旧零件创造新灯具富有创意。'),Q('imaginative',4,1,'Imaginative is formed from imagination plus?','-ive','-less','-ity','-ive','-ive 常构成形容词。','word-formation')]});
D('imagine',{etymology:E('Imagine comes through Old French from Latin imaginari, “to picture or represent in the mind,” from imago, “image.” It means forming a mental picture, supposing something, or thinking of something unreal.','imagine'),contexts:[C('imagine.s1','旅行计划','Imagine standing on the ridge at sunrise, with the whole valley slowly appearing beneath a layer of cloud.','想象一下日出时站在山脊上，整片山谷在云层下方渐渐显现。','Imagine standing on the ridge at sunrise / with the whole valley slowly appearing / beneath a layer / of cloud.','imagine 在此表示在头脑中形成一个画面。','句子邀请读者构想日出的景象。')],mistakes:[M('She imagined the scene by refusing to picture or think about any part of it.','She imagined the scene by forming a mental picture of the ridge and valley.','拒绝构思任何画面不符合 imagine 的心智活动义。')],quiz:[Q('imagine',1,1,'To imagine a scene is to?','form a picture or idea in the mind','make it physically happen','measure its temperature','form a picture or idea in the mind','imagine 可表示在头脑中构想。'),Q('imagine',2,2,'“I imagine the train is late” means?','I suppose or think it is late','I can see the train in a photograph','I have proved it is early','I suppose or think it is late','s2 表示认为、推想。'),Q('imagine',3,3,'To imagine a false excuse is to?','think of something that is not true','write a verified report','move a vehicle','think of something that is not true','s3 可表示编造或想到不真实的事物。'),Q('imagine',4,1,'Which sentence asks someone to visualize?','Imagine a quiet beach at dawn.','The beach was illegal.','The report is illegible.','Imagine a quiet beach at dawn.','祈使句 invite the listener to form a mental scene.','grammar')]});
D('imagist',{etymology:E('Imagist refers to an Imagist poet or to Imagism, the early twentieth-century movement that favored clear, concentrated images and often free verse. The name is based on image.','imagist'),contexts:[C('imagist.s1','文学史课程','The lecturer described H.D. as an Imagist, noting how the poem uses a precise image instead of a long abstract explanation.','讲师把 H.D. 描述为意象派诗人，并指出这首诗用一个精确意象取代冗长抽象的解释。','The lecturer described H.D. as an Imagist / noting how the poem uses a precise image / instead of a long / abstract explanation.','imagist 在此指重视清晰、凝练意象的诗人。','以精确意象代替抽象阐述体现意象派特点。')],mistakes:[M('The critic called a poet an Imagist because the poems avoided images and relied only on lengthy abstract argument.','The critic called the poet an Imagist because the poems used clear, concentrated images.','完全回避意象与意象派强调的诗艺相反。')],quiz:[Q('imagist',1,1,'An Imagist poet aimed for?','clear, concentrated images','long, vague descriptions only','a series of legal arguments','clear, concentrated images','Imagist 诗人强调清晰凝练的意象。'),Q('imagist',2,2,'Imagist can also mean?','relating to the Imagism movement','a person unable to read','a type of wild berry','relating to the Imagism movement','s2 是与意象派运动相关的形容词义。'),Q('imagist',3,1,'Which poem sounds Imagist?','a short poem built around a precise visual image','a long list with no concrete images','a medical report about illness','a short poem built around a precise visual image','以精确视觉意象为中心符合意象派特色。'),Q('imagist',4,1,'Imagist is based on which word?','image','illness','immaculate','image','该名称以 image 为基础。','word-formation')]});
D('imago',{etymology:E('Imago is a Latin word meaning “image” and is used in biology for the final sexually mature form of an insect. In psychology it can mean an unconscious idealized image of a parent or another figure.','imago'),contexts:[C('imago.s1','昆虫学观察','After the final molt, the cicada emerged as an imago, its mature wings ready for flight.','最后一次蜕皮后，蝉以成虫形态出现，成熟的翅膀已能飞行。','After the final molt / the cicada emerged as an imago / its mature wings / ready for flight.','imago 在此指昆虫最后的性成熟阶段，即成虫。','蜕皮后具有成熟翅膀的阶段是成虫。')],mistakes:[M('The entomologist called the newly hatched larva an imago even though it had not completed its growth or final molt.','The entomologist called the fully mature insect after its final molt an imago.','尚未成熟的幼虫不是昆虫的成虫阶段。')],quiz:[Q('imago',1,1,'In insect biology, the imago is the?','final sexually mature form','first egg stage only','temporary larval skin','final sexually mature form','imago 指昆虫的成虫阶段。'),Q('imago',2,2,'In psychology, an imago may be?','an unconscious idealized image of a parent or figure','a kind of insect wing','a legal document','an unconscious idealized image of a parent or figure','s2 指心理上的理想化形象。'),Q('imago',3,1,'A cicada after its final molt is an?','imago','immature larva','illustrator','imago','完成最后蜕皮后的蝉进入成虫期。'),Q('imago',4,1,'The Latin word imago means?','image','illness','law','image','拉丁语 imago 意为形象或图像。','word-formation')]});
D('imbalance',{etymology:E('Imbalance is formed from the negative prefix im- and balance. It means a situation in which two or more things are not in the right proportion or equilibrium.','imbalance'),contexts:[C('imbalance.s1','营养科普','The assessment found an imbalance between sodium and potassium in the sample, prompting the team to review the measurements.','评估发现样本中的钠和钾比例失衡，因此团队重新检查了测量结果。','The assessment found an imbalance / between sodium and potassium / in the sample / prompting the team to review the measurements.','imbalance 指两种或多种成分比例不恰当的状态。','钠钾比例不均衡体现了失衡。')],mistakes:[M('The analyst described equal amounts of both elements as an imbalance, even though their proportions were exactly as intended.','The analyst described the unequal proportions as an imbalance.','比例完全符合要求时不构成失衡。')],quiz:[Q('imbalance',1,1,'An imbalance is?','a lack of proper proportion or balance','a state of perfect equality','a clear picture in a book','a lack of proper proportion or balance','imbalance 指不均衡。'),Q('imbalance',2,1,'Which situation shows an imbalance?','one region receives far more resources than another','all regions receive the planned equal share','a room is evenly lit','one region receives far more resources than another','资源分配悬殊构成失衡。'),Q('imbalance',3,1,'The prefix im- in imbalance means?','not or lack of','very much','again','not or lack of','im- 在此是否定前缀。','word-formation'),Q('imbalance',4,1,'An imbalance in a system may require?','adjusting unequal parts','adding more confusion','ignoring the measurements','adjusting unequal parts','调整不恰当比例可纠正失衡。')]});
D('imbalanced',{etymology:E('Imbalanced is formed from im- plus balanced. It describes something whose parts, forces, or nutrients are not in proper balance.','imbalanced'),contexts:[C('imbalanced.s1','生态监测','The ecologist called the pond imbalanced after one species multiplied rapidly and consumed most of the available food.','一种物种迅速繁殖并消耗了大部分食物后，生态学家认为池塘生态失衡了。','The ecologist called the pond imbalanced / after one species multiplied rapidly / and consumed / most of the available food.','imbalanced 表示各部分或力量缺乏适当平衡的。','单一物种迅速扩张并耗尽资源，破坏了生态平衡。')],mistakes:[M('The ecosystem was called imbalanced even though its populations and resources remained stable and well proportioned.','The ecosystem was called balanced because its populations and resources remained stable.','稳定且比例适当的生态系统不应称为失衡。')],quiz:[Q('imbalanced',1,1,'An imbalanced system has?','parts or forces out of proper proportion','perfectly equal and stable parts','a very clear explanation','parts or forces out of proper proportion','imbalanced 表示失衡的。'),Q('imbalanced',2,1,'An imbalanced diet may lack?','a suitable mix of nutrients','any food at all by definition','all signs of imbalance','a suitable mix of nutrients','营养比例不恰当的饮食可能缺少必要营养组合。'),Q('imbalanced',3,1,'Which pond is imbalanced?','one species overwhelms the others and uses most food','species and resources remain stable','no measurements have been taken','one species overwhelms the others and uses most food','一种物种压倒其他物种会造成生态失衡。'),Q('imbalanced',4,1,'Imbalanced is based on the noun?','imbalance','image','imago','imbalance','imbalanced 由 imbalance 派生。','word-formation')]});
D('imbibe',{etymology:E('Imbibe comes from Latin imbibere, “to drink in,” from in- and bibere, “to drink.” It means to drink, especially alcohol, or to absorb liquid or ideas.','imbibe'),contexts:[C('imbibe.s2','学习习惯','During the workshop, participants imbibed the mentor’s practical advice while taking notes and asking questions.','研讨会期间，参与者一边记笔记和提问，一边吸收导师的实用建议。','During the workshop / participants imbibed the mentor’s practical advice / while taking notes / and asking questions.','imbibe 在此比喻吸收、接受思想或建议。','参与者把导师的建议吸收到自己的理解中。')],mistakes:[M('The trainees imbibed the advice by refusing to listen to it and ignoring every recommendation.','The trainees imbibed the advice by listening carefully and taking it in.','拒绝倾听并忽略建议与吸收思想相反。')],quiz:[Q('imbibe',1,1,'To imbibe a drink is to?','drink it','write it down','make it illegal','drink it','imbibe 可正式或幽默地表示饮用。'),Q('imbibe',2,2,'To imbibe new ideas is to?','absorb them into one’s thinking','pour them onto the floor','copy their sound','absorb them into one’s thinking','s2 指吸收思想或知识。'),Q('imbibe',3,1,'Which sentence uses imbibe figuratively?','The students imbibed the instructor’s advice.','The students imbibed a glass of water.','The students huddled by the door.','The students imbibed the instructor’s advice.','吸收建议是比喻用法。'),Q('imbibe',4,1,'The Latin element bibere meant?','to drink','to read','to balance','to drink','bibere 意为饮用。','word-formation')]});
D('imbrute',{etymology:E('Imbrute is formed from im- and brute, with the verbal sense “to make brutal or become brutal.” It means to reduce a person to a brutal condition or to sink into one.','imbrute'),contexts:[C('imbrute.s1','文学评论','The critic argued that the prison’s degrading routines could imbrute people by stripping away dignity and meaningful choice.','评论家认为，监狱中有辱人格的日常安排可能使人变得粗野，因为它剥夺了尊严和有意义的选择。','The critic argued / that the prison’s degrading routines could imbrute people / by stripping away dignity / and meaningful choice.','imbrute 表示使人陷入野蛮状态或使其变得粗暴。','剥夺尊严和选择会使人遭受粗暴化的影响。')],mistakes:[M('The program was said to imbrute participants by teaching empathy, self-control, and respectful discussion.','The critic warned that degrading treatment could imbrute people by eroding dignity.','培养同理心与克制不会使人变得粗野。')],quiz:[Q('imbrute',1,1,'To imbrute someone is to?','reduce them to a brutal condition','make them more literate','help them absorb an idea','reduce them to a brutal condition','imbrute 表示使人变得粗野或残暴。'),Q('imbrute',2,1,'Which condition could imbrute people?','degrading treatment that strips away dignity','care that supports humane choices','a clear explanation of a topic','degrading treatment that strips away dignity','有辱人格的待遇可能使人粗暴化。'),Q('imbrute',3,1,'Imbrute is formed around the word?','brute','image','hour','brute','imbrute 以 brute 为词根。','word-formation'),Q('imbrute',4,1,'A person who imbrutes themselves may?','sink into brutal behavior','become exceptionally hospitable','learn to read more clearly','sink into brutal behavior','该动词也可表示自己沉沦为粗野状态。')]});
D('imbue',{etymology:E('Imbue comes from Latin imbuere, “to moisten, steep, or dye.” It means to cause a person or thing to be strongly affected by a quality, feeling, or idea.','imbue'),contexts:[C('imbue.s1','艺术评论','The composer imbued the quiet melody with a sense of longing by using slow strings and a rising final phrase.','作曲家用缓慢的弦乐和逐渐上扬的结尾乐句，使这段安静旋律充满思念之情。','The composer imbued the quiet melody / with a sense of longing / by using slow strings / and a rising final phrase.','imbue A with B 表示使 A 充满或深受 B 影响。','旋律通过配器和乐句获得思念的情绪色彩。')],mistakes:[M('The composer imbued the melody with longing by removing every expressive choice and ensuring it conveyed no feeling.','The composer imbued the melody with longing through expressive strings and phrasing.','刻意消除情感表达与赋予旋律某种情绪相反。')],quiz:[Q('imbue',1,1,'To imbue a story with warmth is to?','make it strongly express warmth','remove all feeling from it','translate it into another language','make it strongly express warmth','imbue A with B 表示使 A 充满 B。'),Q('imbue',2,1,'Which sentence uses imbue correctly?','The speech imbued the project with confidence.','The speech imbued the room through a window.','The speech imbued the clock to sixty minutes.','The speech imbued the project with confidence.','演讲使项目充满信心，搭配自然。'),Q('imbue',3,1,'A leader may imbue a team with?','a sense of purpose','a horse’s hoof','a reading difficulty','a sense of purpose','团队可被赋予目标感。'),Q('imbue',4,1,'Imbue originally had an image connected with?','soaking or staining','measuring time','making an illustration','soaking or staining','其词源原与浸润或染色有关。','word-formation')]});
D('imitate',{etymology:E('Imitate comes from Latin imitari, “to copy or represent.” It means copying someone’s actions or speech, making something that looks like another thing, or behaving in the same way as someone else.','imitate'),contexts:[C('imitate.s1','语言学习','The child tried to imitate the teacher’s pronunciation, repeating each phrase slowly until the sounds were clearer.','孩子试着模仿老师的发音，慢慢重复每个短语，直到声音更清楚。','The child tried to imitate the teacher’s pronunciation / repeating each phrase slowly / until the sounds / were clearer.','imitate 在此表示模仿他人的说话方式或行为。','孩子重复老师的发音以学习语音。')],mistakes:[M('The child imitated the teacher by using completely different sounds and refusing to copy any part of the pronunciation.','The child imitated the teacher by copying the pronunciation carefully.','完全不复制声音不符合 imitate 的模仿义。')],quiz:[Q('imitate',1,1,'To imitate a speaker is to?','copy their actions or speech','make them impossible to hear','give them a legal award','copy their actions or speech','imitate 表示模仿。'),Q('imitate',2,2,'A toy may imitate a real car by?','being made to look like one','being unrelated in shape and use','being a person who reads aloud','being made to look like one','s2 指制作外观仿真的物品。'),Q('imitate',3,3,'To imitate a teammate’s routine is to?','behave in the same way','criticize the routine without copying it','measure the teammate’s height','behave in the same way','s3 指以类似方式行动。'),Q('imitate',4,1,'Which is an example of imitation?','copying a bird’s call to learn its sound','inventing a completely unrelated sound','turning off all sound','copying a bird’s call to learn its sound','模仿鸟叫是复制声音。')]});
D('imitation',{etymology:E('Imitation comes from Latin imitatio, from imitari, “to copy.” It means a copy of the real thing, especially one made to resemble an original.','imitation'),contexts:[C('imitation.s1','商品鉴别','The label identifies the bag as an imitation leather product rather than genuine animal hide.','标签说明这只包是仿皮制品，而不是真正的动物皮革。','The label identifies the bag / as an imitation leather product / rather than / genuine animal hide.','imitation 在此指仿制品或仿真材料。','包的材料模仿真皮外观，但不是真皮。')],mistakes:[M('The museum described the original painting as an imitation even though it was the artist’s first authentic work.','The museum described the later copy as an imitation of the original painting.','艺术家的原作不是其后制成的仿品。')],quiz:[Q('imitation',1,1,'An imitation is?','a copy made to resemble a real or original thing','the original item itself','a disease caused by a virus','a copy made to resemble a real or original thing','imitation 指仿制品或模仿。'),Q('imitation',2,1,'Imitation leather is?','material designed to look like leather','genuine animal hide','a type of household cleaner','material designed to look like leather','仿皮模仿真皮外观。'),Q('imitation',3,1,'Which is an imitation?','a replica made to resemble an antique vase','the original vase made by the artist','a photograph of an unrelated room','a replica made to resemble an antique vase','仿制古董花瓶是 imitation。'),Q('imitation',4,1,'Imitation is related to the verb?','imitate','imbue','illuminate','imitate','imitation 是 imitate 的名词形式。','word-formation')]});
D('imitative',{etymology:E('Imitative is formed from imitate with the adjective suffix -ive. It describes something done by copying a model rather than by inventing independently.','imitative'),contexts:[C('imitative.s1','音乐评论','The review called the band’s early songs imitative because their melodies closely copied a better-known group.','评论认为这支乐队早期的歌曲模仿性很强，因为旋律与一支更知名乐队非常相似。','The review called the band’s early songs imitative / because their melodies closely copied / a better-known group.','imitative 表示通过模仿范例而创作的。','旋律紧密复制其他乐队的风格。')],mistakes:[M('The critic called the arrangement imitative even though it introduced a wholly original melody and style.','The critic called the arrangement original because it used a new melody and style.','完全原创的编曲不符合模仿性强的描述。')],quiz:[Q('imitative',1,1,'An imitative work is made by?','copying a model','avoiding all models and influence','measuring its length','copying a model','imitative 表示模仿性的。'),Q('imitative',2,1,'Which song sounds imitative?','one that closely copies another band’s style','one with a wholly new sound','one with no melody at all','one that closely copies another band’s style','紧密复制其他乐队风格的作品带有模仿性。'),Q('imitative',3,1,'Imitative is formed from imitate plus?','-ive','-less','-ity','-ive','-ive 构成形容词。','word-formation'),Q('imitative',4,1,'A design may be called imitative if it?','repeats the features of an existing model','breaks every connection with prior examples','is impossible to see','repeats the features of an existing model','设计复制已有范例时具有模仿性。')]});
D('imitator',{etymology:E('Imitator is formed from imitate plus -or, a suffix naming a person who performs an action. It means someone who copies a model, performer, or product.','imitator'),contexts:[C('imitator.s1','表演节目','The comedian was a skilled imitator who could reproduce the singer’s accent and stage gestures without confusing the audience about who was performing.','这位喜剧演员是出色的模仿者，能重现歌手的口音和舞台动作，同时不让观众误以为本人登台。','The comedian was a skilled imitator / who could reproduce the singer’s accent / and stage gestures / without confusing the audience.','imitator 指模仿他人或某种范例的人。','演员复制口音和动作，属于模仿表演。')],mistakes:[M('The review called the comedian an imitator even though the act avoided copying anyone’s voice, movement, or style.','The review called the comedian an imitator because the act copied a singer’s voice and gestures.','没有模仿任何人的表演不符合 imitator 的含义。')],quiz:[Q('imitator',1,1,'An imitator is someone who?','copies a model or performer','writes laws','grows berries','copies a model or performer','imitator 指模仿者。'),Q('imitator',2,1,'A celebrity imitator might reproduce the person’s?','voice and gestures','blood type and medical records','legal permit','voice and gestures','模仿者常复制名人的口音和动作。'),Q('imitator',3,1,'The suffix -or in imitator often names?','a person who does something','a condition or quality','a way of moving','a person who does something','-or 可表示动作执行者。','word-formation'),Q('imitator',4,1,'Which person is an imitator?','a performer copying a famous singer’s style','a singer creating a new style','a listener who hears the song once','a performer copying a famous singer’s style','复制歌手风格的表演者是模仿者。')]});
D('immaculate',{etymology:E('Immaculate comes from Latin immaculatus, “unstained,” formed from in- and macula, “spot or stain.” It describes something so clean or correct that no fault can be seen.','immaculate'),contexts:[C('immaculate.s1','展馆维护','The curator kept the white sculpture immaculate, removing each speck of dust before the gallery opened.','策展人在展厅开放前清除每一点灰尘，使白色雕塑保持一尘不染。','The curator kept the white sculpture immaculate / removing each speck of dust / before the gallery opened.','immaculate 表示极其干净、没有污点或瑕疵的。','作品表面没有尘污，符合一尘不染的描述。')],mistakes:[M('The review described the stained, damaged display as immaculate even though several visible marks remained.','The review described the spotless, undamaged display as immaculate.','明显有污渍和损坏的展品不符合 immaculate。')],quiz:[Q('immaculate',1,1,'An immaculate room is?','extremely clean and without visible faults','dirty and damaged','difficult to understand','extremely clean and without visible faults','immaculate 表示一尘不染、无瑕的。'),Q('immaculate',2,1,'An immaculate record contains?','no errors or blemishes','many unresolved mistakes','only imaginary events','no errors or blemishes','该词也可形容记录完美无误。'),Q('immaculate',3,1,'Which surface is immaculate?','a spotless freshly cleaned table','a table covered in mud','a rough damaged floor','a spotless freshly cleaned table','没有污点的桌面符合 immaculate。'),Q('immaculate',4,1,'The Latin element macula meant?','spot or stain','light','guest','spot or stain','macula 意为斑点或污迹。','word-formation')]});
D('immaterial',{etymology:E('Immaterial combines the negative prefix im- with material. It can mean not physical or, in an argument, not important or relevant.','immaterial'),contexts:[C('immaterial.s1','哲学讨论','The philosopher described the mind as immaterial in the argument, treating it as distinct from physical matter.','在这段论证中，哲学家把心智描述为非物质的，认为它不同于物理物质。','The philosopher described the mind as immaterial / in the argument / treating it as distinct / from physical matter.','immaterial 在此表示非物质的、非实体的。','论证将心智与物理物质区分开来。')],mistakes:[M('The report called the machine immaterial even though it was a heavy physical object made of steel.','The report called the idea immaterial because it was not a physical object.','沉重钢制机器是实体物，不符合非物质义。')],quiz:[Q('immaterial',1,1,'An immaterial idea is?','not physical','made of solid steel','impossible to read','not physical','immaterial 可表示非物质的。'),Q('immaterial',2,1,'In a discussion, a detail is immaterial if it is?','not important or relevant','the central point','a legal requirement','not important or relevant','immaterial 也表示无关紧要。'),Q('immaterial',3,1,'Which is immaterial in a debate about a bridge’s safety?','the color of a reporter’s notebook','the condition of the bridge supports','the load the bridge can bear','the color of a reporter’s notebook','记者笔记本的颜色与桥梁安全无关。'),Q('immaterial',4,1,'The prefix im- in immaterial means?','not','very','under','not','im- 是否定前缀。','word-formation')]});
D('immature',{etymology:E('Immature combines the negative prefix im- with mature, from Latin maturus, “ripe or fully developed.” It means not fully grown or developed.','immature'),contexts:[C('immature.s1','农业观察','The growers left the immature tomatoes on the vine because the fruit was still small and green.','种植者把尚未成熟的番茄留在藤上，因为果实仍然又小又绿。','The growers left the immature tomatoes on the vine / because the fruit / was still small / and green.','immature 表示尚未充分发育或成熟的。','小而青的番茄还未成熟。')],mistakes:[M('The growers picked the immature tomatoes at full ripeness after they had turned red and soft.','The growers picked the mature tomatoes after they had turned red and soft.','已经完全成熟变红的番茄不能称为未成熟。')],quiz:[Q('immature',1,1,'An immature fruit is?','not fully grown or ripe','ready to harvest at full maturity','a public impression','not fully grown or ripe','immature 表示尚未成熟或发育完全。'),Q('immature',2,1,'Which plant is immature?','a small green tomato still developing','a ripe red tomato ready to pick','a dried seed packet','a small green tomato still developing','仍在生长的小绿番茄尚未成熟。'),Q('immature',3,1,'Immature is the opposite of?','mature','immaterial','imaginary','mature','mature 与 immature 相反。'),Q('immature',4,1,'The prefix im- means?','not','again','between','not','im- 是否定前缀。','word-formation')]});
D('immaturity',{etymology:E('Immaturity is formed from immature plus -ity, a suffix making an abstract noun. It means a lack of full development in the body or in behavior.','immaturity'),contexts:[C('immaturity.s1','教育反馈','The coach noted the team’s immaturity when players blamed one another instead of discussing how to improve after a loss.','输球后球员们互相指责而不是讨论如何改进，教练因此指出了球队的不成熟。','The coach noted the team’s immaturity / when players blamed one another / instead of discussing / how to improve after a loss.','immaturity 指身体或行为尚未充分成熟的状态。','输球后推卸责任体现行为上的不成熟。')],mistakes:[M('The coach praised the team’s immaturity because the players calmly accepted responsibility and learned from the loss.','The coach praised the team’s maturity because the players accepted responsibility and learned from the loss.','冷静负责并吸取教训体现成熟，而非不成熟。')],quiz:[Q('immaturity',1,1,'Immaturity is?','a lack of full development','the quality of being perfectly mature','an inability to read handwriting','a lack of full development','immaturity 指不成熟的状态。'),Q('immaturity',2,1,'Which behavior suggests immaturity?','blaming teammates instead of taking responsibility','admitting a mistake and learning from it','considering evidence before speaking','blaming teammates instead of taking responsibility','推卸责任是行为不成熟的表现。'),Q('immaturity',3,1,'Immaturity is formed from immature plus?','-ity','-ful','-or','-ity','-ity 构成抽象名词。','word-formation'),Q('immaturity',4,1,'A lack of physical development is also called?','immaturity','illumination','hospitality','immaturity','该词可指身体发育未充分成熟。')]});
D('immeasurable',{etymology:E('Immeasurable combines the negative prefix im- with measurable, from measure. It means so great in degree that no measure can adequately capture it.','immeasurable'),contexts:[C('immeasurable.s1','纪念仪式','The volunteers said the community’s support had been of immeasurable value during the recovery effort.','志愿者们说，在复原工作中，社区支持的价值难以估量。','The volunteers said / the community’s support had been of immeasurable value / during the recovery effort.','immeasurable 表示程度大到无法衡量的。','支持的价值无法用具体尺度充分衡量。')],mistakes:[M('The team called the effect immeasurable because it had measured it precisely as zero.','The team called the effect immeasurable because no practical measure captured its full importance.','被精确测为零与无法衡量的巨大程度不符。')],quiz:[Q('immeasurable',1,1,'Immeasurable value is?','too great to measure adequately','exactly zero','easy to count in units','too great to measure adequately','immeasurable 表示难以衡量、巨大无比的。'),Q('immeasurable',2,1,'Which may be immeasurable?','the importance of long-term community support','the length of a ruler','the number of chairs in a room','the importance of long-term community support','抽象价值难以精确量化。'),Q('immeasurable',3,1,'Immeasurable is opposite in form to?','measurable','immaculate','immobile','measurable','measurable 表示可测量的，与之相反。','word-formation'),Q('immeasurable',4,1,'An immeasurable contribution is?','so significant that a simple measurement cannot capture it','a contribution counted exactly as one item','a contribution that never happened','so significant that a simple measurement cannot capture it','该词强调程度极大而难以量化。')]});
D('immeasurably',{etymology:E('Immeasurably is the adverb formed from immeasurable plus -ly. It means by an amount or to a degree too great to calculate or measure.','immeasurably'),contexts:[C('immeasurably.s1','研究总结','The new drainage system improved the residents’ safety immeasurably by reducing flood damage across the neighborhood.','新排水系统大幅提升了居民的安全，因为它减少了整个社区的洪灾损失。','The new drainage system improved the residents’ safety immeasurably / by reducing flood damage / across the neighborhood.','immeasurably 表示程度极大、难以测量地。','洪灾损失减少使安全程度有巨大改善。')],mistakes:[M('The report said safety improved immeasurably by exactly one millimeter, a precisely measured tiny amount.','The report said safety improved measurably by a small, precisely measured amount.','精确测出的微小变化不符合 immeasurably 所指的难以量化程度。')],quiz:[Q('immeasurably',1,1,'To improve immeasurably is to improve?','by an amount too great to calculate','by a precisely known tiny amount','without any change','by an amount too great to calculate','immeasurably 表示变化大到难以计算。'),Q('immeasurably',2,1,'Which sentence uses immeasurably naturally?','The repair improved the bridge’s safety immeasurably.','The ruler measured immeasurably exactly 10 cm.','She immeasurably the door with a key.','The repair improved the bridge’s safety immeasurably.',' immeasurably 修饰程度难以量化的改善。'),Q('immeasurably',3,1,'Immeasurably is formed from immeasurable plus?','-ly','-ness','-er','-ly','-ly 构成副词。','word-formation'),Q('immeasurably',4,1,'Immeasurably differs from slightly because it describes?','an enormous or uncalculable degree','a small exact change','a time of day','an enormous or uncalculable degree','它强调极大或难以计算的程度。')]});
D('immediate',{etymology:E('Immediate comes from Latin immediatus, “without anything between,” formed from in- and medius, “middle.” It means happening at once, closest in relationship or space, or most urgent.','immediate'),contexts:[C('immediate.s4','安全提示','The operator treated the smoke alarm as an immediate priority and evacuated the building before checking the equipment.','操作员把烟雾警报视为当务之急，在检查设备前先疏散了大楼。','The operator treated the smoke alarm as an immediate priority / and evacuated the building / before checking / the equipment.','immediate 在此表示最紧急、最需要优先处理的。','警报需要立刻优先应对。')],mistakes:[M('The operator called the smoke alarm an immediate priority but postponed action for several months.','The operator treated the smoke alarm as an urgent matter and acted at once.','最紧急的事项不应被无故拖延数月。')],quiz:[Q('immediate',1,1,'An immediate response happens?','at once','after several years','only if a guest arrives','at once','immediate 可表示立即发生或完成。'),Q('immediate',2,2,'An immediate family member is?','a close relative','a distant business competitor','a person who cannot read','a close relative','s2 指关系最近的亲属。'),Q('immediate',3,3,'The immediate area is?','the nearest surrounding space','a place far beyond the horizon','a period of sixty minutes','the nearest surrounding space','s3 表示空间或时间上最近的。'),Q('immediate',4,4,'An immediate danger is?','the most urgent or pressing danger','a distant possibility only','a familiar household item','the most urgent or pressing danger','s4 表示迫切需要处理的危险。')]});
D('immediately',{etymology:E('Immediately is formed from immediate plus -ly. It means at once or without delay.','immediately'),contexts:[C('immediately.s1','应急流程','When the alarm sounded, staff immediately guided visitors to the nearest safe exit.','警报响起后，工作人员立即引导访客前往最近的安全出口。','When the alarm sounded / staff immediately guided visitors / to the nearest / safe exit.','immediately 表示立刻、毫不拖延地。','警报响后工作人员马上行动。')],mistakes:[M('The staff responded immediately by waiting a week before directing visitors to an exit.','The staff responded immediately by guiding visitors to an exit at once.','等待一周才行动不符合 immediately。')],quiz:[Q('immediately',1,1,'If staff act immediately, they act?','at once','after a long delay','only the next day','at once','immediately 表示立即地。'),Q('immediately',2,1,'Which sentence uses immediately correctly?','Please report the leak immediately.','Immediately means at some unknown point next year.','They immediately the package yesterday.','Please report the leak immediately.','发现漏水后应立即报告。'),Q('immediately',3,1,'The suffix -ly in immediately forms?','an adverb','a plural noun','a person’s title','an adverb','-ly 常把形容词变为副词。','word-formation'),Q('immediately',4,1,'Immediately is closest in meaning to?','without delay','eventually','occasionally','without delay','without delay 与 immediately 意思相近。')]});
D('immense',{etymology:E('Immense comes from Latin immensus, “immeasurable,” formed from in- and mensus, “measured.” It means extremely large in size or amount, very great in degree, or informally extremely good.','immense'),contexts:[C('immense.s1','天文观察','The observatory’s new image revealed an immense cloud of gas stretching far beyond the neighboring star system.','天文台的新图像显示，一大片巨大的气体云延伸到邻近恒星系统之外。','The observatory’s new image revealed an immense cloud of gas / stretching far beyond / the neighboring star system.','immense 在此表示尺寸或范围极其巨大。','气体云跨越邻近恒星系统，规模宏大。')],mistakes:[M('The astronomer called a speck of dust immense even though it was smaller than the surrounding grains.','The astronomer called the vast gas cloud immense.','微小尘粒不符合 immense 的巨大含义。')],quiz:[Q('immense',1,1,'An immense object is?','extremely large','very small','impossible to read','extremely large','immense 表示极其巨大的。'),Q('immense',2,2,'Immense effort means?','a very great degree of effort','a very small amount of work','a public image','a very great degree of effort','s2 描述程度或数量极大。'),Q('immense',3,3,'In informal praise, “That was immense!” can mean?','That was extremely good.','That was illegal.','That was hard to hear.','That was extremely good.','s3 是口语中“非常棒”的用法。'),Q('immense',4,1,'Which landscape could be called immense?','a plain stretching beyond the horizon','a tiny mark on a page','a small closed box','a plain stretching beyond the horizon','广阔延伸的平原可称 immense。')]});
D('immensely',{etymology:E('Immensely is the adverb formed from immense plus -ly. It means very much or to an enormous extent.','immensely'),contexts:[C('immensely.s1','项目回顾','The improved lighting helped the gallery immensely, making the labels and smaller artworks easy to see.','照明改进对展厅帮助极大，使说明牌和较小的作品都清晰可见。','The improved lighting helped the gallery immensely / making the labels / and smaller artworks / easy to see.','immensely 表示程度很大、极其地。','照明带来显著改善。')],mistakes:[M('The new lighting helped immensely by making no difference at all to what visitors could see.','The new lighting helped immensely by making more details visible.','毫无变化不能称为帮助极大。')],quiz:[Q('immensely',1,1,'To enjoy a concert immensely is to enjoy it?','very much','not at all','for exactly one hour','very much','immensely 表示非常、极其。'),Q('immensely',2,1,'Which sentence is natural?','The update improved the app immensely.','The update immensely the app yesterday.','The app is an immensely.','The update improved the app immensely.','immensely 可修饰 improved，表示改进很大。'),Q('immensely',3,1,'Immensely is the adverb from?','immense','immediate','immobile','immense','immensely 由 immense 加 -ly 构成。','word-formation'),Q('immensely',4,1,'If a task helps immensely, it helps?','to an enormous extent','only a tiny bit','in an unlawful way','to an enormous extent','该副词强调帮助程度极大。')]});
D('immensity',{etymology:E('Immensity is formed from immense plus -ity, an abstract-noun suffix. It means huge scale or extent.','immensity'),contexts:[C('immensity.s1','海洋纪录片','The narrator paused to emphasize the immensity of the ocean, which covers most of the planet’s surface.','旁白停顿了一下，强调海洋的浩瀚；海洋覆盖了地球表面的大部分区域。','The narrator paused / to emphasize the immensity of the ocean / which covers most / of the planet’s surface.','immensity 指规模或范围巨大。','海洋覆盖地球大部分表面，范围极广。')],mistakes:[M('The speaker described the immensity of a tiny pebble that fit inside a grain of sand.','The speaker described the immensity of the ocean and its vast extent.','微小鹅卵石不符合 immensity 所指的浩大规模。')],quiz:[Q('immensity',1,1,'The immensity of a mountain range is its?','huge scale or extent','small weight','ease of reading','huge scale or extent','immensity 指巨大规模或广阔范围。'),Q('immensity',2,1,'Which thing may have immensity?','an ocean spanning much of a planet','a tiny button','one short sentence','an ocean spanning much of a planet','覆盖广阔区域的海洋体现浩瀚。'),Q('immensity',3,1,'Immensity is related to the adjective?','immense','impatient','impartial','immense','immensity 由 immense 派生。','word-formation'),Q('immensity',4,1,'A person overwhelmed by immensity may feel?','small before something vast','certain that nothing is large','unable to hear a sound','small before something vast','浩瀚规模可能让人感到自身渺小。')]});
D('immerge',{etymology:E('Immerge is formed from the Latin prefix in- and mergere, “to dip or sink.” It means to go down into a liquid or to sink from view; immerse is the more common related verb.','immerge'),contexts:[C('immerge.s1','水文学观察','As the water level rose, the lower marker on the river gauge began to immerge beneath the surface.','水位上涨时，河流水尺下方的刻度开始没入水面之下。','As the water level rose / the lower marker on the river gauge / began to immerge / beneath the surface.','immerge 表示进入液体或沉入水中。','刻度逐渐被水面遮没，体现下沉义。')],mistakes:[M('The marker immerged by rising completely out of the water and remaining dry above the surface.','The marker immerged as the rising water covered it and carried it below the surface.','浮出水面与沉入水中方向相反。')],quiz:[Q('immerge',1,1,'To immerge is to?','go down into a liquid or sink from view','rise above the water','explain an idea clearly','go down into a liquid or sink from view','immerge 表示没入或沉入。'),Q('immerge',2,1,'Which object immerges?','a stone sinking below the pond surface','a balloon rising into the air','a lamp illuminating a room','a stone sinking below the pond surface','石头沉入水中符合 immerge。'),Q('immerge',3,1,'Which verb is more common and closely related?','immerse','immolate','imitate','immerse','immerse 是更常见的相关动词。'),Q('immerge',4,1,'The Latin element mergere meant?','to dip or sink','to write','to welcome a guest','to dip or sink','mergere 与浸入或下沉有关。','word-formation')]});
D('immerse',{etymology:E('Immerse comes from Latin immergere, “to plunge into,” formed from in- and mergere, “to dip.” It can mean putting something fully under liquid or becoming deeply involved in an activity, or involving someone deeply.','immerse'),contexts:[C('immerse.s2','语言学习','For the summer, Ana immersed herself in Japanese by joining a conversation group and reading local newspapers each day.','暑假期间，安娜通过参加会话小组并每天阅读当地报纸，全身心投入日语学习。','For the summer / Ana immersed herself in Japanese / by joining a conversation group / and reading local newspapers each day.','immerse oneself in 表示全身心投入某项活动或学习。','参加会话并每日阅读体现深度投入。')],mistakes:[M('Ana immersed herself in Japanese by avoiding all lessons, conversations, reading, and contact with the language.','Ana immersed herself in Japanese by practicing conversation and reading daily.','完全回避语言活动不符合全身投入的含义。')],quiz:[Q('immerse',1,1,'To immerse a cup in water is to?','put it completely under the liquid','hold it above the surface','make it easier to understand','put it completely under the liquid','immerse 的字面义是完全浸入液体。'),Q('immerse',2,2,'To immerse yourself in a language is to?','become deeply involved in learning it','avoid hearing or reading it','translate one word once','become deeply involved in learning it','s2 指全身心投入语言学习。'),Q('immerse',3,3,'A teacher may immerse students in a topic by?','involving them deeply in related activities','removing every example','keeping them away from the subject','involving them deeply in related activities','s3 表示使他人深度参与某主题。'),Q('immerse',4,1,'Which is literal immersion?','submerging a cloth fully in dye','reading about a subject','joining a discussion group','submerging a cloth fully in dye','把布完全浸入染液是字面义。')]});
D('immersion',{etymology:E('Immersion is formed from immerse plus -ion. It means the act of covering something completely with liquid or the state of being deeply involved in an activity or language.','immersion'),contexts:[C('immersion.s2','语言课程','The program uses immersion in Spanish, so students hear and speak the language throughout ordinary classroom activities.','课程采用西班牙语沉浸式教学，因此学生在日常课堂活动中一直听说西班牙语。','The program uses immersion in Spanish / so students hear and speak the language / throughout ordinary / classroom activities.','immersion 在此指全程置身于某语言环境的学习方式。','学生在课堂活动中持续使用西班牙语。')],mistakes:[M('The course called itself language immersion although students never heard, read, or spoke the target language.','The course used language immersion by surrounding students with the target language.','没有接触目标语言不符合沉浸式学习。')],quiz:[Q('immersion',1,1,'Immersion in a liquid is?','covering something completely with it','keeping an object above it','drying an object in air','covering something completely with it','immersion 可指完全浸没。'),Q('immersion',2,2,'Language immersion involves?','deep exposure to and use of the language','avoiding the language entirely','memorizing only its name','deep exposure to and use of the language','s2 指深入语言环境的沉浸式学习。'),Q('immersion',3,1,'Which course offers immersion?','one where learners use the language throughout the day','one where learners never encounter it','one consisting only of a final exam','one where learners use the language throughout the day','全程使用目标语言的课程具有沉浸式特点。'),Q('immersion',4,1,'Immersion is the noun related to?','immerse','immense','imagine','immerse','immersion 是 immerse 的名词形式。','word-formation')]});
D('immigrant',{etymology:E('Immigrant comes from Latin immigrant-, “moving into,” from immigrare, “to move into.” It names a person who comes to live in a different country and can also be an adjective relating to such people.','immigrant'),contexts:[C('immigrant.s1','社区访谈','The immigrant opened a neighborhood bakery after settling in the country and learning how local customers preferred their bread.','这位移民在该国定居并了解当地顾客喜欢的面包后，开了一家社区面包店。','The immigrant opened a neighborhood bakery / after settling in the country / and learning / how local customers preferred their bread.','immigrant 在此作名词，指迁居到另一个国家生活的人。','人物迁入新国家并在当地定居。')],mistakes:[M('The article called a tourist staying for one weekend an immigrant, although the visitor had no intention of moving there.','The article called the person who settled in the country an immigrant.','短期旅游者没有迁居意图，不等同于移民。')],quiz:[Q('immigrant',1,1,'An immigrant is someone who?','comes to live in a different country','visits a country for a short holiday only','hosts a television program','comes to live in a different country','immigrant 指迁居到另一国家的人。'),Q('immigrant',2,2,'An immigrant community is?','relating to people who moved to live in a country','a group of short-term tourists only','a hospital department','relating to people who moved to live in a country','s2 作形容词，表示与移民相关。'),Q('immigrant',3,1,'Which person is most clearly an immigrant?','someone who settles permanently in a new country','someone taking a two-day vacation','someone changing seats on a train','someone who settles permanently in a new country','迁居定居而非短期旅行符合 immigrant。'),Q('immigrant',4,1,'Immigrant is related to which verb?','immigrate','illuminate','imitate','immigrate','immigrant 与 immigrate 同源。','word-formation')]});
D('immigrate',{etymology:E('Immigrate comes from Latin immigrare, “to move into,” formed from in- and migrare, “to move.” It means coming to a different country in order to live there permanently.','immigrate'),contexts:[C('immigrate.s1','个人经历','Her grandparents immigrated to Canada in the 1960s and built a new life near their extended family.','她的祖父母在 20 世纪 60 年代移民加拿大，并在亲属附近建立了新生活。','Her grandparents immigrated to Canada / in the 1960s / and built a new life / near their extended family.','immigrate 表示迁入另一国家以在那里生活。','句中说明迁入加拿大并开始定居生活。')],mistakes:[M('They immigrated to Canada for a weekend sightseeing trip and returned home two days later.','They visited Canada for a weekend and immigrated only if they moved there to live.','短暂观光旅行不等于移民定居。')],quiz:[Q('immigrate',1,1,'To immigrate to a country is to?','move there to live','leave it for a short tour','visit its airport in transit','move there to live','immigrate 表示迁入并在当地生活。'),Q('immigrate',2,1,'A family may immigrate when it?','settles in a new country','takes a one-day sightseeing trip','changes homes within the same street','settles in a new country','迁居并定居新国家符合 immigrate。'),Q('immigrate',3,1,'Immigrate focuses on moving?','into a country','out of a country','around a city only','into a country','immigrate 的方向是迁入。','word-formation'),Q('immigrate',4,1,'The noun for the process of immigrating is?','immigration','immensity','immobility','immigration','immigration 指移民迁入过程。')]});
D('immigration',{etymology:E('Immigration is formed from immigrate plus -ion. It means the process of coming to live in a country, especially by people moving from another country.','immigration'),contexts:[C('immigration.s1','公共政策','The report compares immigration levels over ten years and explains how the figures were collected.','报告比较了十年来的移民迁入水平，并说明这些数据是如何收集的。','The report compares immigration levels / over ten years / and explains / how the figures were collected.','immigration 指迁入一个国家生活的过程或现象。','报告按年份比较跨国迁入人数。')],mistakes:[M('The report defined immigration as people leaving a country to settle elsewhere, regardless of where they enter.','The report defined immigration as people coming into a country to live there.','离开本国称为 emigration；immigration 强调迁入。')],quiz:[Q('immigration',1,1,'Immigration is the process of?','coming to live in a country','leaving a country permanently','visiting a place for one afternoon','coming to live in a country','immigration 指移民迁入。'),Q('immigration',2,1,'A policy on immigration concerns?','people entering a country to settle','only people leaving it','the price of a hotel room','people entering a country to settle','相关政策关注迁入者及其定居。'),Q('immigration',3,1,'Which pair is correct?','immigrate: move into; immigration: the process','immigrate: read; immigration: a book','immigrate: grow; immigration: a flower','immigrate: move into; immigration: the process','动词表示迁入，名词表示迁入过程。','word-formation'),Q('immigration',4,1,'A report on immigration might count?','people moving into a country','people buying household goods','hours in a workday','people moving into a country','移民数据常统计迁入人口。')]});
D('imminent',{etymology:E('Imminent comes from Latin imminere, “to overhang or threaten,” from in- and minere, “to project.” It means about to happen very soon or so near in time that it could happen at any moment.','imminent'),contexts:[C('imminent.s1','天气预警','The meteorologist warned that flooding was imminent as the river rose rapidly and heavy rain continued upstream.','河水迅速上涨且上游仍有大雨，气象学家因此警告洪水即将到来。','The meteorologist warned / that flooding was imminent / as the river rose rapidly / and heavy rain continued upstream.','imminent 表示某事很快就要发生。','水位快速上升，洪灾迫近。')],mistakes:[M('The report called the flood imminent even though the river was dry and no rain was forecast for months.','The report called the flood imminent because the river was rising rapidly after heavy rain.','没有水情或降雨迹象时不能说洪水迫在眉睫。')],quiz:[Q('imminent',1,1,'An imminent event is?','about to happen very soon','already completed years ago','impossible to imagine','about to happen very soon','imminent 表示即将发生的。'),Q('imminent',2,2,'An imminent danger is one that?','is so close it may occur at any moment','is only a remote possibility','has no connection to the present','is so close it may occur at any moment','s2 强调危险近在眼前。'),Q('imminent',3,1,'Which event seems imminent?','a storm as dark clouds arrive and warnings are issued','a festival scheduled for ten years later','a meeting that ended yesterday','a storm as dark clouds arrive and warnings are issued','天气预警和乌云显示风暴迫近。'),Q('imminent',4,1,'Imminent is often used about?','an approaching event or danger','a polished clean surface','a person’s public image','an approaching event or danger','常用于描述迫近的事件或危险。')]});
D('immobile',{etymology:E('Immobile comes from Latin immobilis, formed from in- and mobilis, “movable.” It means still or unable to be moved.','immobile'),contexts:[C('immobile.s1','物理观察','The heavy cabinet remained immobile after the movers locked its wheels and secured it against the wall.','搬运工锁住柜子的轮子并将其固定在墙边后，沉重的柜子纹丝不动。','The heavy cabinet remained immobile / after the movers locked its wheels / and secured it / against the wall.','immobile 表示静止或无法移动的。','柜子被锁定并固定，不能移动。')],mistakes:[M('The cabinet was called immobile while it rolled freely across the room with unlocked wheels.','The cabinet was called mobile while it rolled freely across the room.','能自由滚动的柜子不是 immobile。')],quiz:[Q('immobile',1,1,'An immobile object is?','still or unable to be moved','moving quickly','easy to read','still or unable to be moved','immobile 指不动或无法移动的。'),Q('immobile',2,1,'Which object is immobile?','a cabinet bolted to the floor','a rolling suitcase being pulled','a bird flying overhead','a cabinet bolted to the floor','固定在地上的柜子无法移动。'),Q('immobile',3,1,'Immobile is the opposite of?','mobile','imminent','immense','mobile','mobile 表示可移动，与 immobile 相反。'),Q('immobile',4,1,'The prefix im- in immobile means?','not','before','across','not','im- 是否定前缀。','word-formation')]});
D('immobility',{etymology:E('Immobility is formed from immobile plus -ity, a suffix making an abstract noun. It means the condition of being unable or unwilling to move.','immobility'),contexts:[C('immobility.s1','康复记录','The therapist monitored the patient’s temporary immobility after the leg injury and adjusted the exercises as movement returned.','腿部受伤后，治疗师观察患者暂时无法活动的状况，并随着活动能力恢复调整练习。','The therapist monitored the patient’s temporary immobility / after the leg injury / and adjusted the exercises / as movement returned.','immobility 指无法或不愿移动的状态。','受伤后暂时不能活动体现 immobility。')],mistakes:[M('The report described the runner’s full-speed movement as immobility.','The report described the runner’s inability to move after the injury as immobility.','快速移动与 immobility 的静止状态相反。')],quiz:[Q('immobility',1,1,'Immobility is the condition of?','being unable or unwilling to move','moving at high speed','being extremely famous','being unable or unwilling to move','immobility 指不能或不愿移动的状态。'),Q('immobility',2,1,'Temporary immobility may follow?','a leg injury','a successful race','a clear explanation','a leg injury','腿部受伤可能导致暂时不能活动。'),Q('immobility',3,1,'Immobility is formed from immobile plus?','-ity','-ful','-er','-ity','-ity 构成抽象名词。','word-formation'),Q('immobility',4,1,'A person experiencing immobility may need?','support while movement is limited','a faster vehicle','a more vivid image','support while movement is limited','行动受限时可能需要协助。')]});
D('immobilize',{etymology:E('Immobilize combines the negative prefix im- with mobilize, “make movable,” and the verb suffix -ize. It means to prevent a limb, vehicle, or force from moving.','immobilize'),contexts:[C('immobilize.s1','急救训练','In the training exercise, responders used a splint to immobilize the injured wrist before moving the patient.','在训练演习中，救援人员先用夹板固定受伤手腕，再移动伤者。','In the training exercise / responders used a splint / to immobilize the injured wrist / before moving the patient.','immobilize 表示使肢体或物体不能移动。','夹板限制手腕移动以减少转运中的晃动。')],mistakes:[M('The splint immobilized the wrist by letting it bend freely in every direction.','The splint immobilized the wrist by holding it steady.','允许手腕自由弯曲与固定其活动相反。')],quiz:[Q('immobilize',1,1,'To immobilize an injured wrist is to?','prevent it from moving','make it stronger instantly','measure its temperature','prevent it from moving','immobilize 表示使不能移动。'),Q('immobilize',2,1,'A security device may immobilize a vehicle by?','preventing it from being driven','refueling it','cleaning its windshield','preventing it from being driven','防盗设备可阻止车辆移动。'),Q('immobilize',3,1,'Which tool might immobilize a broken limb?','a splint','a garden hose','a printed illustration','a splint','夹板可限制受伤肢体活动。'),Q('immobilize',4,1,'The suffix -ize often forms a verb meaning?','to make or cause to be','a person who does something','a state or condition','to make or cause to be','-ize 常表示使成为或造成某状态。','word-formation')]});
D('immodesty',{etymology:E('Immodesty is formed from immodest plus -y. It means boastful behavior or dress and conduct regarded as improper or lacking modesty.','immodesty'),contexts:[C('immodesty.s1','人物评论','The reviewer criticized the speaker’s immodesty, noting that he repeatedly claimed sole credit for work done by the whole team.','评论者批评演讲者缺乏谦逊，指出他反复把整个团队完成的工作都归功于自己。','The reviewer criticized the speaker’s immodesty / noting that he repeatedly claimed sole credit / for work done / by the whole team.','immodesty 在此指自夸、不谦逊的行为。','独占团队成果体现自大而不谦虚。')],mistakes:[M('The reviewer praised the speaker’s immodesty because he openly credited every teammate and avoided boasting.','The reviewer praised the speaker’s modesty because he credited the team and avoided boasting.','谦逊并感谢团队与 immodesty 相反。')],quiz:[Q('immodesty',1,1,'Immodesty can mean?','boastful behavior','quiet humility','difficulty moving','boastful behavior','immodesty 可指自夸、缺乏谦逊。'),Q('immodesty',2,1,'Which action shows immodesty?','claiming sole credit for a team’s work','thanking each colleague for a contribution','admitting uncertainty','claiming sole credit for a team’s work','把集体成果占为己有显得自大。'),Q('immodesty',3,1,'Immodesty is the opposite of?','modesty','immobility','immensity','modesty','modesty 表示谦逊，与 immodesty 相反。'),Q('immodesty',4,1,'Immodesty may also describe conduct viewed as?','improper or lacking modesty','especially clear and readable','about to happen','improper or lacking modesty','该词也可指被认为不端庄的举止或穿着。')]});
D('immolate',{etymology:E('Immolate comes from Latin immolare, originally “to sprinkle sacrificial meal,” and later “to sacrifice.” It means to kill a person or animal as an offering, often by burning.','immolate'),contexts:[C('immolate.s1','历史研究','The historian used immolate to describe an ancient account of a life being sacrificed in a ritual, without endorsing the practice.','历史学家用 immolate 描述古代记载中的仪式性献祭，并不表示赞同这种做法。','The historian used immolate / to describe an ancient account / of a life being sacrificed in a ritual / without endorsing the practice.','immolate 指将人或动物作为祭品杀死，常与焚烧相关。','语境为历史描述，并明确不认可献祭行为。')],mistakes:[M('The historian said immolate meant to welcome a guest with a meal and no sacrifice occurred.','The historian used immolate for the ritual sacrifice described in the account.','招待客人进餐与献祭义不同。')],quiz:[Q('immolate',1,1,'To immolate a victim historically meant to?','kill them as a sacrifice','welcome them as a guest','teach them to read','kill them as a sacrifice','immolate 指作为祭品杀死。'),Q('immolate',2,1,'An account may describe an animal being immolated in?','a sacrificial ritual','a routine veterinary check','a school reading lesson','a sacrificial ritual','献祭仪式中可能使用 immolate 描述牺牲行为。'),Q('immolate',3,1,'Immolate is a word for?','sacrifice, often by burning','making a room brighter','moving into another country','sacrifice, often by burning','该词常指献祭，历史上常涉及焚烧。'),Q('immolate',4,1,'A historian using immolate is describing?','a sacrifice in a historical source','ordinary hospitality','a person’s inability to move','a sacrifice in a historical source','该词在此用于历史性描述。')]});
D('immolation',{etymology:E('Immolation is formed from immolate plus -ion. It means the act of sacrificing a life, often by burning.','immolation'),contexts:[C('immolation.s1','古代史课程','The chapter discusses immolation in ancient ritual sources and distinguishes documented practices from later legends.','本章讨论古代仪式文献中的献祭行为，并区分有文献记载的做法与后来的传说。','The chapter discusses immolation / in ancient ritual sources / and distinguishes documented practices / from later legends.','immolation 指献祭生命这一行为，常见于历史或宗教语境。','章节比较文献记载与传说中的献祭。')],mistakes:[M('The chapter defined immolation as a peaceful welcome ceremony with no sacrifice or loss of life.','The chapter defined immolation as the act of sacrificing a life.','没有献祭或生命牺牲的欢迎仪式不是 immolation。')],quiz:[Q('immolation',1,1,'Immolation is the act of?','sacrificing a life','welcoming a visitor','illustrating a book','sacrificing a life','immolation 指献祭行为。'),Q('immolation',2,1,'A history text may discuss immolation in connection with?','ancient ritual sacrifice','ordinary hotel housekeeping','a modern reading test','ancient ritual sacrifice','历史文本可能讨论古代仪式献祭。'),Q('immolation',3,1,'Immolation is the noun related to?','immolate','immerse','immigrate','immolate','immolation 由 immolate 派生。','word-formation'),Q('immolation',4,1,'Which detail belongs to the meaning of immolation?','a life offered as a sacrifice','a person moving to a new country','a fixed sixty-minute period','a life offered as a sacrifice','献出生命作为祭品是该词的核心义。')]});
D('immoral',{etymology:E('Immoral is formed from the negative prefix im- and moral, from Latin moralis, “relating to conduct or custom.” It means contrary to accepted standards of right and wrong.','immoral'),contexts:[C('immoral.s1','职业伦理','The editor refused to publish an immoral advertisement that targeted vulnerable people with false promises.','编辑拒绝刊登一则不道德的广告，因为它用虚假承诺针对弱势群体。','The editor refused to publish an immoral advertisement / that targeted vulnerable people / with false promises.','immoral 表示违背道德规范的。','利用虚假承诺伤害弱势群体被视为不道德行为。')],mistakes:[M('The board called the honest disclosure immoral even though it prevented customers from being misled.','The board called the deceptive advertisement immoral because it preyed on vulnerable customers.','诚实披露并避免欺骗并非不道德。')],quiz:[Q('immoral',1,1,'An immoral act is?','contrary to accepted standards of right and wrong','required by every ethical code','impossible to measure','contrary to accepted standards of right and wrong','immoral 表示不道德的。'),Q('immoral',2,1,'Which action is immoral?','deceiving vulnerable customers with false claims','admitting a mistake and correcting it','giving accurate safety information','deceiving vulnerable customers with false claims','利用虚假信息欺骗弱势顾客违反道德。'),Q('immoral',3,1,'Immoral is the opposite of?','moral','immense','immobile','moral','moral 与 immoral 意义相反。'),Q('immoral',4,1,'The prefix im- contributes the meaning?','not','again','very','not','im- 是否定前缀。','word-formation')]});
D('immortal',{etymology:E('Immortal comes from Latin immortalis, “not subject to death,” formed from in- and mortalis, “mortal.” It describes someone or something living forever or remaining famous, and can name an undying god or remembered person.','immortal'),contexts:[C('immortal.s1','文学评论','The poet’s final collection made her name immortal among readers who continued to quote the poems decades later.','诗人的最后一部诗集使她在读者心中名垂不朽，几十年后人们仍在引用她的诗。','The poet’s final collection made her name immortal / among readers / who continued to quote the poems / decades later.','immortal 在此比喻因作品而长久流传、被人铭记的。','多年后仍被引用的诗作让诗人留名。')],mistakes:[M('The historian called the artist immortal because everyone forgot the work immediately after its release.','The historian called the artist immortal because the work remained famous across generations.','作品迅速被遗忘与永垂不朽相反。')],quiz:[Q('immortal',1,1,'An immortal being is traditionally?','living forever or unable to die','unable to move','too small to measure','living forever or unable to die','immortal 可指不死的、长生的。'),Q('immortal',2,2,'“A literary immortal” can be?','a person remembered for lasting achievement','a person who cannot read','an official immune from tax','a person remembered for lasting achievement','s2 指会被永远铭记的人。'),Q('immortal',3,1,'Which work might make a name immortal?','a famous poem remembered for centuries','an anonymous note discarded unread','a temporary schedule','a famous poem remembered for centuries','世代传诵的作品可使作者留名。'),Q('immortal',4,1,'Immortal is the opposite of?','mortal','moral','immaterial','mortal','mortal 表示终有一死的，与 immortal 相反。')]});
D('immune',{etymology:E('Immune comes from Latin immunis, “exempt or free from public service,” and later developed medical and broader senses. It can mean protected against a disease, unaffected by something, or not subject to a law or tax.','immune'),contexts:[C('immune.s1','医学科普','Vaccination can help make a person immune to a disease by preparing the body’s defenses to recognize it.','接种疫苗可帮助人体产生针对某种疾病的免疫力，使身体防御系统能够识别它。','Vaccination can help make a person immune to a disease / by preparing the body’s defenses / to recognize it.','immune 在此表示具有抵抗某种疾病的免疫保护。','疫苗帮助身体识别病原体并建立防御。')],mistakes:[M('The patient was described as immune to the disease despite having no protection and becoming infected immediately.','The patient was described as vulnerable because they had no protection against the disease.','没有保护且感染不能证明具有免疫力。')],quiz:[Q('immune',1,1,'A person immune to a disease is?','protected against it','certain to catch it','unable to read about it','protected against it','immune 的医学义是对疾病有免疫保护。'),Q('immune',2,2,'“Immune to criticism” means?','not affected by criticism','protected from a virus only','legally accused of a crime','not affected by criticism','s2 表示不受某种影响。'),Q('immune',3,3,'A person immune from a tax is?','not subject to that tax','paying the tax twice','unaware of the tax','not subject to that tax','s3 指免于承担某项义务。'),Q('immune',4,1,'Which phrase uses immune figuratively?','immune to pressure','immune to a loud sound as a physical disease','immune the door closed','immune to pressure','不受压力影响是比喻用法。')]});
D('immunisation',{etymology:E('Immunisation is the British spelling of immunization, formed from immunise plus -ation. It means protecting a person against disease, commonly by vaccination.','immunisation'),contexts:[C('immunisation.s1','公共卫生','The clinic’s immunisation program offers routine vaccines to children according to the national schedule.','诊所的免疫接种项目按照国家日程为儿童提供常规疫苗。','The clinic’s immunisation program / offers routine vaccines / to children / according to the national schedule.','immunisation 指通过接种等方式使人获得疾病防护的过程。','常规疫苗用于帮助儿童预防疾病。')],mistakes:[M('The clinic called immunisation a way of making patients more likely to catch the disease being prevented.','The clinic described immunisation as a way to protect patients against disease.','免疫接种旨在提供保护，不是增加感染风险。')],quiz:[Q('immunisation',1,1,'Immunisation protects people against disease, often by?','vaccination','imitation','immigration','vaccination','immunisation 常通过接种疫苗提供疾病防护。'),Q('immunisation',2,1,'The spelling immunisation is usual in?','British English','only ancient Greek','mathematical equations','British English','immunisation 是英式拼法，美式常写 immunization。','grammar'),Q('immunisation',3,1,'Which service might provide immunisation?','a public health clinic','a hotel reception desk','a garden center','a public health clinic','公共卫生诊所可提供疫苗接种服务。'),Q('immunisation',4,1,'Immunisation is intended to increase?','protection from a disease','exposure to a disease','difficulty moving','protection from a disease','免疫接种的目标是增强防护。')]});
D('immunity',{etymology:E('Immunity comes from Latin immunitas, “exemption or privilege,” related to immunis. It can mean the body’s ability to resist disease or official freedom from prosecution, tax, or another obligation.','immunity'),contexts:[C('immunity.s1','健康教育','The nurse explained that immunity can develop after exposure to a germ or through vaccination, while reminding the group that protection varies.','护士解释，接触病原体或接种疫苗后都可能形成免疫力，同时提醒大家保护程度因人而异。','The nurse explained / that immunity can develop after exposure to a germ / or through vaccination / while reminding the group that protection varies.','immunity 在此指身体抵抗特定疾病的能力。','接触病原体或接种疫苗可帮助建立免疫防御。')],mistakes:[M('The brochure promised complete immunity to every disease after one ordinary meal.','The brochure explained that immunity to a particular disease can develop through vaccination or exposure.','普通一餐不能保证对所有疾病获得完全免疫。')],quiz:[Q('immunity',1,1,'Biological immunity is the body’s ability to?','resist a particular disease','read unclear writing','move without stopping','resist a particular disease','immunity 可指身体抵抗疾病的能力。'),Q('immunity',2,2,'Legal immunity may provide?','official freedom from prosecution or an obligation','protection from every virus','a hotel room','official freedom from prosecution or an obligation','s2 指法律上的豁免。'),Q('immunity',3,1,'Which phrase uses immunity legally?','diplomatic immunity','herd immunity in a biology lesson','immune response to a virus','diplomatic immunity','外交豁免属于法律义。'),Q('immunity',4,1,'Immunity is related to the adjective?','immune','immense','impatient','immune','immunity 与 immune 同源。','word-formation')]});
D('immutable',{etymology:E('Immutable comes from Latin immutabilis, “unchangeable,” formed from in- and mutabilis, “changeable.” It means not subject to change.','immutable'),contexts:[C('immutable.s1','软件设计','The system treats the archived transaction record as immutable so that later edits cannot alter the original entry.','系统将归档交易记录视为不可更改，以防后续编辑改变原始记录。','The system treats the archived transaction record as immutable / so that later edits / cannot alter / the original entry.','immutable 表示不会或不能改变的。','系统禁止修改原始记录。')],mistakes:[M('The database called a record immutable even though any user could freely rewrite or delete it.','The database called a locked record immutable because it could not be changed.','可任意改写的记录并非不可变。')],quiz:[Q('immutable',1,1,'An immutable rule is?','not subject to change','changed every hour','hard to read','not subject to change','immutable 表示不可改变的。'),Q('immutable',2,1,'Which data might be immutable?','a permanent archived record protected from edits','a draft that anyone can rewrite','a temporary note erased each day','a permanent archived record protected from edits','受保护且无法修改的归档记录符合 immutable。'),Q('immutable',3,1,'Immutable is the opposite of?','changeable','immoral','illogical','changeable','changeable 与 immutable 意义相反。'),Q('immutable',4,1,'The prefix im- in immutable contributes?','not','many','after','not','im- 是否定前缀。','word-formation')]});
D('imp',{etymology:E('Imp comes from Old English impa, “young shoot or offspring,” and later came to mean a small mischievous devil or sprite.','imp'),contexts:[C('imp.s1','民间故事','In the folktale, a mischievous imp hid the baker’s wooden spoon and giggled when the family searched for it.','民间故事里，一个顽皮的小恶魔藏起了面包师的木勺，看到一家人四处寻找时咯咯笑。','In the folktale / a mischievous imp hid the baker’s wooden spoon / and giggled / when the family searched for it.','imp 指顽皮的小恶魔或小精灵。','角色恶作剧藏起木勺，体现其顽皮特性。')],mistakes:[M('The tale called the quiet village librarian an imp even though she never played tricks or caused mischief.','The tale called the mischievous sprite who hid the spoon an imp.','安静且不淘气的人不符合 imp 的顽皮小恶魔义。')],quiz:[Q('imp',1,1,'An imp in a folktale is usually?','a small mischievous devil or sprite','a respected public official','a large garden plant','a small mischievous devil or sprite','imp 常指顽皮的小恶魔或小精灵。'),Q('imp',2,1,'Which character might be called an imp?','a playful sprite hiding a spoon','a careful judge reading a case','a nurse giving a vaccine','a playful sprite hiding a spoon','爱恶作剧的小精灵符合 imp。'),Q('imp',3,1,'The imp’s behavior is likely?','mischievous','immobile','impartial','mischievous','imp 常带有顽皮淘气的特点。'),Q('imp',4,1,'The older source of imp first related to?','a young shoot or offspring','a legal exemption','a picture in a book','a young shoot or offspring','词源早期与幼苗或后代有关。','word-formation')]});
D('impact',{etymology:E('Impact comes from Latin impactus, “driven or pressed in,” from impingere, “to strike against.” As a noun it means a strong effect or a forceful collision; as a verb it means to affect or hit with force.','impact'),contexts:[C('impact.s4','政策评估','The new fare policy will impact commuters who rely on the first bus of the morning.','新的票价政策会影响依赖早班公交的通勤者。','The new fare policy will impact commuters / who rely on the first bus / of the morning.','impact 在此作动词，表示对某人或某事产生影响。','票价变化会影响通勤者的出行安排。')],mistakes:[M('The policy impacted commuters by having no effect on their fares, routes, or travel decisions.','The policy impacted commuters by changing the fares they paid.','完全没有影响与 impact 作动词的含义相反。')],quiz:[Q('impact',1,1,'A strong impact on a community is?','a powerful effect','a small household object','a type of vaccine','a powerful effect','impact 作名词可指强烈影响。'),Q('impact',2,2,'The impact of a car crash can be?','the force of one object hitting another','a person’s immunity','an image in a poem','the force of one object hitting another','s2 指碰撞时的冲击力。'),Q('impact',3,4,'A new rule may impact a business by?','affecting how it operates','making a loud animal cry','causing a person to read','affecting how it operates','impact 作动词表示影响。'),Q('impact',4,5,'A meteorite can impact the ground when it?','hits it with force','hovers above it forever','becomes a public image','hits it with force','impact 也可表示猛烈撞击。')]});
D('impair',{etymology:E('Impair comes from Old French empeirier, “to make worse,” from Latin peior, “worse.” It means to damage or weaken something, worsen a physical ability, or reduce value or quality.','impair'),contexts:[C('impair.s2','公共安全','The doctor warned that severe fatigue can impair a driver’s reaction time and make it harder to respond to sudden hazards.','医生警告，严重疲劳会损害驾驶员的反应时间，使其更难应对突发危险。','The doctor warned / that severe fatigue can impair a driver’s reaction time / and make it harder / to respond to sudden hazards.','impair 在此表示损害或削弱人的身体能力。','疲劳会降低反应能力。')],mistakes:[M('The review said fatigue impaired the driver by making reactions faster and improving hazard awareness.','The review said fatigue impaired the driver by slowing reactions and reducing awareness.','反应变快、意识增强与损害能力相反。')],quiz:[Q('impair',1,1,'To impair a machine is to?','damage or weaken its function','improve it perfectly','make it impossible to see','damage or weaken its function','impair 表示损害或削弱。'),Q('impair',2,2,'Fatigue can impair a person’s?','physical ability or reaction time','public image','household goods','physical ability or reaction time','s2 涉及身体能力下降。'),Q('impair',3,3,'Poor materials may impair a product’s?','value or quality','temperature only','number of hours','value or quality','s3 表示降低价值或质量。'),Q('impair',4,1,'Which change impairs a phone?','a cracked screen that stops it responding','a repair that restores its function','a new battery that works normally','a cracked screen that stops it responding','屏幕损坏并影响运行属于损害。')]});
D('impale',{etymology:E('Impale comes through French from Latin palus, “stake.” It means to pierce a body or object with a sharp stake or point.','impale'),contexts:[C('impale.s1','小说阅读','The adventure novel describes a spear striking the wooden shield, but the narrator makes clear that no person is impaled.','冒险小说描写长矛击中木盾，但叙述者明确说明没有人被刺穿。','The adventure novel describes a spear striking the wooden shield / but the narrator makes clear / that no person / is impaled.','impale 表示用尖桩或尖锐物刺穿。','句子解释该词并说明被击中的是木盾而非人体。')],mistakes:[M('The report said the blunt pillow impaled the target, although it had no point and caused no puncture.','The report used impale only for piercing with a sharp point or stake.','无尖端且未刺穿的软枕头不可能 impale 目标。')],quiz:[Q('impale',1,1,'To impale an object is to?','pierce it with a sharp point','cover it with a soft cloth','make it easier to understand','pierce it with a sharp point','impale 表示用尖物刺穿。'),Q('impale',2,1,'Which event would impale a target?','a sharp stake piercing it','a soft ball touching it gently','a lamp shining on it','a sharp stake piercing it','尖桩刺入物体符合 impale。'),Q('impale',3,1,'Impale is most closely associated with?','a sharp point or stake','a household chore','a public impression','a sharp point or stake','该词常与尖桩等刺穿物相关。'),Q('impale',4,1,'Which sentence uses impale correctly?','The sharp branch impaled the cardboard model.','The pillow impaled the model without touching it.','The student impaled the answer by explaining it.','The sharp branch impaled the cardboard model.','尖枝刺穿纸板模型符合用法。')]});
D('impart',{etymology:E('Impart comes from Latin impartire, “to share or give a part,” formed from in- and pars, “part.” It means passing on knowledge, giving information, or giving a particular quality to something.','impart'),contexts:[C('impart.s1','师徒培训','The senior technician imparted practical skills to the apprentices by demonstrating how to calibrate the instruments.','资深技术员通过演示如何校准仪器，把实用技能传授给学徒。','The senior technician imparted practical skills / to the apprentices / by demonstrating / how to calibrate the instruments.','impart 在此表示把知识或技能传授给别人。','技术员通过示范向学徒传授技能。')],mistakes:[M('The technician imparted the skill by hiding the instructions and refusing to demonstrate the procedure.','The technician imparted the skill by explaining and demonstrating the procedure.','隐瞒知识不符合传授技能的含义。')],quiz:[Q('impart',1,1,'To impart a skill is to?','pass it on to someone','keep it entirely secret','make it illegal','pass it on to someone','impart 可表示传授知识或技能。'),Q('impart',2,2,'To impart information is to?','give it to someone','remove it from a report','make it difficult to read','give it to someone','s2 指提供信息。'),Q('impart',3,3,'A spice can impart what to food?','a particular flavor or quality','a legal exemption','a sharp point','a particular flavor or quality','s3 表示赋予事物某种特质。'),Q('impart',4,1,'Which sentence uses impart correctly?','The mentor imparted confidence to the new team.','The mentor imparted the meeting yesterday.','The mentor imparted by refusing to speak.','The mentor imparted confidence to the new team.','impart A to B 可表示把某种特质赋予 B。')]});
D('impartial',{etymology:E('Impartial combines the negative prefix im- with partial, from Latin pars, “part.” It means treating all sides equally without favoring one party.','impartial'),contexts:[C('impartial.s1','争议调解','Both companies agreed to use an impartial mediator who had no financial connection to either side.','两家公司同意聘请一位公正的调解人，此人与任何一方都没有经济关系。','Both companies agreed to use an impartial mediator / who had no financial connection / to either side.','impartial 表示不偏袒任何一方、公正的。','调解人没有利益关系，能够平等听取双方意见。')],mistakes:[M('The mediator was impartial because she accepted payment from only one company and ignored the other side.','The mediator was impartial because she had no connection to either company and heard both sides.','只收一方报酬并忽视另一方体现偏袒。')],quiz:[Q('impartial',1,1,'An impartial judge?','treats all sides fairly','favors one party secretly','cannot move','treats all sides fairly','impartial 表示公正、不偏不倚。'),Q('impartial',2,1,'Which person is most likely impartial?','a reviewer with no connection to either applicant','a judge who is related to one applicant','a witness paid by one side','a reviewer with no connection to either applicant','没有关联或利益冲突的评审更可能公正。'),Q('impartial',3,1,'Impartial is the opposite of?','biased','immortal','immediate','biased','biased 表示有偏见，与 impartial 相反。'),Q('impartial',4,1,'The prefix im- in impartial means?','not','between','after','not','im- 是否定前缀。','word-formation')]});
D('impartially',{etymology:E('Impartially is the adverb formed from impartial plus -ly. It means without taking sides or serving a private interest.','impartially'),contexts:[C('impartially.s1','竞赛评审','The judges scored each entry impartially, using the same published criteria for every contestant.','评委们公正地为每件作品打分，对每位参赛者都使用相同的公开标准。','The judges scored each entry impartially / using the same published criteria / for every contestant.','impartially 表示不偏袒地、公正地。','所有参赛者使用相同标准，体现公平评判。')],mistakes:[M('The judges scored impartially by giving their friends higher marks regardless of the published criteria.','The judges scored impartially by applying the same criteria to every entry.','偏袒朋友不符合公正评分。')],quiz:[Q('impartially',1,1,'To act impartially is to act?','without taking sides','in favor of a relative','without any evidence','without taking sides','impartially 表示公正地、不偏袒地。'),Q('impartially',2,1,'A panel judges impartially when it?','uses the same standards for everyone','changes rules for its friends','ignores all applications','uses the same standards for everyone','一视同仁地使用标准体现公正。'),Q('impartially',3,1,'Impartially is formed from impartial plus?','-ly','-ness','-ful','-ly','-ly 把 impartial 变为副词。','word-formation'),Q('impartially',4,1,'Which sentence uses impartially correctly?','The referee impartially enforced the rules.','The referee impartialed the rules.','The referee acted impartially by favoring one team.','The referee impartially enforced the rules.','公正地执行规则是自然用法。')]});
D('impasse',{etymology:E('Impasse came from French impasse, literally a passage with no exit, from in- and passer, “to pass.” It means a deadlock or situation with no way forward.','impasse'),contexts:[C('impasse.s1','谈判纪要','Negotiations reached an impasse when neither side would accept the proposed timetable or offer an alternative.','双方都不接受所提时间表、也不提出替代方案后，谈判陷入僵局。','Negotiations reached an impasse / when neither side would accept the proposed timetable / or offer / an alternative.','impasse 指无法继续推进的僵局。','双方都拒绝妥协或提供替代方案，谈判停滞。')],mistakes:[M('The talks were at an impasse because both sides had agreed to every point and signed the final plan.','The talks were at an impasse because neither side would compromise.','双方已达成一致并签约，就不再处于僵局。')],quiz:[Q('impasse',1,1,'An impasse is?','a deadlock with no way forward','a clear agreement','an imminent event','a deadlock with no way forward','impasse 指僵局。'),Q('impasse',2,1,'Negotiators reach an impasse when?','neither side can agree or move ahead','both sides sign the agreement','one side gives a clear explanation','neither side can agree or move ahead','无法达成协议或继续推进时形成僵局。'),Q('impasse',3,1,'Which phrase is closest to impasse?','dead end','public image','housework','dead end','dead end 与 impasse 意义相近。'),Q('impasse',4,1,'The French source of impasse literally suggested?','a passage with no exit','a room full of light','a group of guests','a passage with no exit','词源字面意象是无出口的通道。','word-formation')]});
D('impassible',{etymology:E('Impassible comes from Latin impassibilis, “incapable of suffering,” formed from in- and passibilis, “capable of feeling.” It means not capable of suffering or being moved by emotion; it differs from impassive, which describes outward expression.','impassible'),contexts:[C('impassible.s1','哲学讨论','The text describes the deity as impassible, meaning incapable of suffering or being changed by human emotions.','文本把神描述为 impassible，意思是不能承受痛苦或被人类情绪改变。','The text describes the deity as impassible / meaning incapable of suffering / or being changed / by human emotions.','impassible 表示不能受苦或被情感触动。','句中直接说明其无法承受痛苦或因情绪改变。')],mistakes:[M('The essay used impassible to mean that a person hid visible tears while feeling intense grief.','The essay used impassive for someone who felt grief but showed little outward emotion.','感到痛苦却不显露表情是 impassive，而非不能感受痛苦的 impassible。')],quiz:[Q('impassible',1,1,'An impassible being is traditionally?','incapable of suffering or being moved by feeling','unable to wait patiently','full of strong emotion','incapable of suffering or being moved by feeling','impassible 表示不能感受痛苦或情绪。'),Q('impassible',2,1,'Impassible differs from impassive because impassible means?','unable to suffer, not merely hiding emotion','showing no emotion while feeling it','becoming impatient while waiting','unable to suffer, not merely hiding emotion','impassible 讲不能感受，impassive 讲不显露。'),Q('impassible',3,1,'Which description fits impassible?','not capable of being emotionally affected','quietly concealing sadness','deeply moved by a speech','not capable of being emotionally affected','不能被情感触动符合 impassible。'),Q('impassible',4,1,'The prefix im- here contributes?','not','very','again','not','im- 是否定前缀。','word-formation')]});
D('impassioned',{etymology:E('Impassioned is formed from passion with the prefix im- and participial ending -ed. It means full of strong emotion and sincere force.','impassioned'),contexts:[C('impassioned.s1','议会发言','The council heard an impassioned appeal from residents who described how the proposed closure would affect elderly neighbors.','市议会听取了居民充满激情的陈情，他们说明拟议中的关闭措施会如何影响年长邻居。','The council heard an impassioned appeal / from residents / who described how the proposed closure / would affect elderly neighbors.','impassioned 形容充满强烈感情和诚挚力量的。','居民以强烈情感陈述关闭措施的影响。')],mistakes:[M('The speaker gave an impassioned address in a flat, detached voice, expressing no feeling or conviction.','The speaker gave an impassioned address with visible conviction and strong emotion.','毫无情绪与信念的表达不符合 impassioned。')],quiz:[Q('impassioned',1,1,'An impassioned speech is?','full of strong feeling and sincere force','quietly indifferent','impossible to understand','full of strong feeling and sincere force','impassioned 表示充满激情的。'),Q('impassioned',2,1,'Which speaker sounds impassioned?','one who speaks earnestly about a cause','one who reads a list without expression','one who refuses to discuss the issue','one who speaks earnestly about a cause','真挚有力地表达信念体现激情。'),Q('impassioned',3,1,'An impassioned appeal may be?','emotionally forceful','unaffected and expressionless','a legal exemption','emotionally forceful','恳切有力的陈情带有强烈情感。'),Q('impassioned',4,1,'Impassioned is related to the noun?','passion','impasse','image','passion','impassioned 与 passion（热情）相关。','word-formation')]});
D('impassive',{etymology:E('Impassive combines the negative prefix im- with passive, from Latin passivus. It describes someone who shows little or no feeling on the face or in behavior, even in a moving situation.','impassive'),contexts:[C('impassive.s1','庭审观察','The witness remained impassive while the lawyer read the threatening message aloud, showing no visible reaction.','律师大声宣读威胁信息时，证人仍面无表情，没有明显反应。','The witness remained impassive / while the lawyer read the threatening message aloud / showing / no visible reaction.','impassive 表示不显露情感或反应的。','证人面对威胁信息没有外在反应。')],mistakes:[M('The witness was impassive and visibly sobbed, shouted, and showed every emotion on her face.','The witness was impassive and showed no visible reaction.','明显哭喊并充分表达情绪与 impassive 相反。')],quiz:[Q('impassive',1,1,'An impassive expression shows?','little or no outward feeling','intense visible excitement','a strong wish to act soon','little or no outward feeling','impassive 指不动声色的。'),Q('impassive',2,1,'A person may remain impassive while?','showing no visible response to upsetting news','cheering loudly with joy','crying openly','showing no visible response to upsetting news','没有明显反应符合 impassive。'),Q('impassive',3,1,'Impassive describes outward expression; impassible describes?','inability to suffer or be moved by feeling','visible excitement','a legal charge','inability to suffer or be moved by feeling','impassible 指不能感受，二者不要混淆。'),Q('impassive',4,1,'Which face is impassive?','a calm face showing no reaction','a face twisted in obvious anger','a smiling face greeting guests','a calm face showing no reaction','没有明显表情变化是 impassive。')]});
D('impatient',{etymology:E('Impatient comes from Latin impatiens, “not enduring,” formed from in- and patiens, “suffering or enduring.” It can mean annoyed by waiting, eager for something to happen, or unable to accept something without irritation.','impatient'),contexts:[C('impatient.s1','候诊室','Several passengers became impatient when the delayed train announcement was postponed for a third time.','列车晚点通知第三次推迟后，几名乘客变得不耐烦。','Several passengers became impatient / when the delayed train announcement / was postponed / for a third time.','impatient 在此表示因等待或事情缓慢而烦躁。','通知反复推迟使乘客失去耐心。')],mistakes:[M('The passengers were impatient with the delay but sat happily for hours and felt no annoyance at all.','The passengers became impatient because the delay frustrated them.','完全没有烦躁感与不耐烦的状态不符。')],quiz:[Q('impatient',1,1,'An impatient person may be?','annoyed by waiting','happy to wait indefinitely','unable to be moved physically','annoyed by waiting','impatient 可指等待时感到烦躁。'),Q('impatient',2,2,'“She is impatient for the results” means she is?','eager for them to arrive soon','angry that they have already arrived','uninterested in them','eager for them to arrive soon','s2 表示急切盼望某事发生。'),Q('impatient',3,3,'Someone impatient with interruptions?','cannot accept them without annoyance','welcomes every interruption','does not notice them','cannot accept them without annoyance','s3 表示无法容忍某事而不烦躁。'),Q('impatient',4,1,'Which reaction is impatient?','checking the clock repeatedly during a long delay','calmly waiting without concern','offering guests refreshments','checking the clock repeatedly during a long delay','反复看时间体现等候时的不耐烦。')]});
D('impeach',{etymology:E('Impeach comes through Old French empechier, “to hinder or accuse,” from Latin impedire, “to entangle.” It means formally accusing a senior public official of serious wrongdoing or challenging a statement’s credibility.','impeach'),contexts:[C('impeach.s1','政府报道','The lower chamber voted to impeach the governor after an inquiry found evidence of serious misconduct.','调查发现严重不当行为的证据后，下议院投票决定弹劾州长。','The lower chamber voted to impeach the governor / after an inquiry found evidence / of serious misconduct.','impeach 在此表示正式指控高级公职人员严重失职。','议会调查后启动正式弹劾程序。')],mistakes:[M('The report said lawmakers impeached the governor by formally praising the conduct and closing the investigation.','The report said lawmakers voted to impeach the governor after alleging serious misconduct.','表扬并结束调查不是正式指控。')],quiz:[Q('impeach',1,1,'To impeach a senior official is to?','formally accuse them of serious wrongdoing','elect them to a new office','make them immune from all laws','formally accuse them of serious wrongdoing','impeach 可指正式弹劾高级官员。'),Q('impeach',2,2,'To impeach a witness’s credibility is to?','raise doubts about whether the witness can be trusted','appoint the witness to office','make the witness immortal','raise doubts about whether the witness can be trusted','s2 指质疑证词或证人的可信度。'),Q('impeach',3,1,'Which action could lead to an impeachment process?','a formal investigation into serious official misconduct','a routine meeting with no allegation','a public award for good service','a formal investigation into serious official misconduct','正式调查严重不当行为可能引发弹劾程序。'),Q('impeach',4,1,'Impeach is most strongly associated with?','formal accusation or a challenge to credibility','household cleaning','a picture in a book','formal accusation or a challenge to credibility','该词涉及正式指控或可信度质疑。')]});
D('impeccable',{etymology:E('Impeccable comes from Latin impeccabilis, “not liable to sin,” formed from in- and peccare, “to sin or make a fault.” It means without any mistake, fault, or bad feature.','impeccable'),contexts:[C('impeccable.s1','礼仪点评','The host’s impeccable timing kept the ceremony on schedule, with each speaker introduced exactly when expected.','主持人把握时间无可挑剔，使典礼按计划进行，每位发言者都准时得到介绍。','The host’s impeccable timing / kept the ceremony on schedule / with each speaker introduced / exactly when expected.','impeccable 表示没有差错或缺点的、无可挑剔的。','准确准时使主持安排十分完美。')],mistakes:[M('The reviewer called the presentation impeccable even though it contained several factual errors and missed every deadline.','The reviewer called the presentation flawed because it contained errors and missed deadlines.','多处错误和逾期与 impeccable 相反。')],quiz:[Q('impeccable',1,1,'Impeccable work is?','without mistakes or faults','full of errors','impossible to read','without mistakes or faults','impeccable 表示无可挑剔的。'),Q('impeccable',2,1,'Which service is impeccable?','a meal served correctly and exactly on time','a delayed meal with wrong orders','a room with broken equipment','a meal served correctly and exactly on time','准确及时且无差错的服务可称 impeccable。'),Q('impeccable',3,1,'Impeccable is closest to?','flawless','illogical','immature','flawless','flawless 与 impeccable 意义相近。'),Q('impeccable',4,1,'The Latin root peccare meant?','to sin or make a fault','to welcome a guest','to light a room','to sin or make a fault','peccare 与犯错相关，im- 否定其含义。','word-formation')]});

})();
